        let code = "my_func <- function(x,\n                    y,\n                    z = 1) { x + y + z }";
        let tree = parse_r(code);
        let artifacts = compute_artifacts(&test_uri(), &tree, code);

        assert_eq!(artifacts.exported_interface.len(), 1);
