    #[test]
    fn interface_hash_distinguishes_current_frame_from_non_inheriting_source() {
        let current = "source(\"child.R\", local = TRUE)";
        let unknown = "source(\"child.R\", local = flag)";
        let current_artifacts = compute_artifacts(&test_uri(), &parse_r(current), current);
        let unknown_artifacts = compute_artifacts(&test_uri(), &parse_r(unknown), unknown);

        assert_ne!(
            current_artifacts.interface_hash, unknown_artifacts.interface_hash,
            "the precise locality must invalidate interfaces even though both legacy local booleans are true"
        );
    }

    #[test]
    fn interface_hash_includes_finalized_source_orderability() {
        let orderable = r#"bquote(expr = .(source("child.R")), where = parent.frame())"#;
        let inverted = r#"bquote(expr = .(source("child.R")), where = { x <- 1; parent.frame() })"#;
        let orderable_tree = parse_r(orderable);
        let inverted_tree = parse_r(inverted);
        let orderable_metadata =
            crate::cross_file::extract_metadata_with_tree(orderable, Some(&orderable_tree));
        let inverted_metadata =
            crate::cross_file::extract_metadata_with_tree(inverted, Some(&inverted_tree));

        assert_eq!(
            orderable_metadata.sources, inverted_metadata.sources,
            "the raw ForwardSource metadata must remain identical"
        );

        let orderable_artifacts = compute_artifacts_with_metadata(
            &test_uri(),
            &orderable_tree,
            orderable,
            Some(&orderable_metadata),
        );
        let inverted_artifacts = compute_artifacts_with_metadata(
            &test_uri(),
            &inverted_tree,
            inverted,
            Some(&inverted_metadata),
        );
        assert!(
            orderable_artifacts
                .timeline
                .iter()
                .any(|event| matches!(event, ScopeEvent::Source { .. })),
            "the orderable capture must lend its source event"
        );
        assert!(
            !inverted_artifacts
                .timeline
                .iter()
                .any(|event| matches!(event, ScopeEvent::Source { .. })),
            "the coordinate-inverted capture must suppress its source event"
        );
        assert_ne!(
            orderable_artifacts.interface_hash, inverted_artifacts.interface_hash,
            "the finalized source lending decision must invalidate the interface"
        );
    }

    #[test]
    fn test_interface_hash_changes_when_top_level_rm_added() {
        // Adding a top-level `rm(y)` must change interface_hash because it
        // alters which symbols are visible at downstream `source()` call
        // sites. Without this, cross-file revalidation never fires when
        // the user inserts an `rm()` between a definition and a `source()`,
        // leaving stale undefined-variable diagnostics in the child file.
        let code1 = "y <- 1\nsource(\"child.R\")";
        let code2 = "y <- 1\nrm(y)\nsource(\"child.R\")";
        let tree1 = parse_r(code1);
        let tree2 = parse_r(code2);
        let artifacts1 = compute_artifacts(&test_uri(), &tree1, code1);
        let artifacts2 = compute_artifacts(&test_uri(), &tree2, code2);

        assert_ne!(
            artifacts1.interface_hash, artifacts2.interface_hash,
            "interface_hash must change when a top-level rm() is inserted"
        );
    }

    #[test]
    fn test_interface_hash_changes_when_top_level_rm_target_changes() {
        // Changing which symbol an rm() targets must change the hash, even
        // though the rm() count and position is unchanged.
        let code1 = "x <- 1\ny <- 2\nrm(x)";
        let code2 = "x <- 1\ny <- 2\nrm(y)";
        let tree1 = parse_r(code1);
        let tree2 = parse_r(code2);
        let artifacts1 = compute_artifacts(&test_uri(), &tree1, code1);
        let artifacts2 = compute_artifacts(&test_uri(), &tree2, code2);

        assert_ne!(artifacts1.interface_hash, artifacts2.interface_hash);
    }

    #[test]
    fn test_interface_hash_changes_when_top_level_rm_moves() {
        // Moving an rm() across a `source()` call changes which symbols
        // the sourced file inherits — the hash must reflect the line.
        let code1 = "y <- 1\nrm(y)\nsource(\"child.R\")";
        let code2 = "y <- 1\nsource(\"child.R\")\nrm(y)";
        let tree1 = parse_r(code1);
        let tree2 = parse_r(code2);
        let artifacts1 = compute_artifacts(&test_uri(), &tree1, code1);
        let artifacts2 = compute_artifacts(&test_uri(), &tree2, code2);

        assert_ne!(
            artifacts1.interface_hash, artifacts2.interface_hash,
            "interface_hash must reflect rm() line because it determines which sourced files see the symbol"
        );
    }

    #[test]
    fn test_interface_hash_changes_when_exists_added_despite_real_def() {
        // An `exists("x")` declaration shadowed by a later real `x <- 1` does
        // not change the exported interface (the real def wins), but it DOES
        // change what a backward-edge dependent sees at the `exists()` line.
        // Both files export the same `x`; only the presence of the `exists()`
        // declaration differs, so interface_hash must still change — otherwise
        // adding/removing the `exists()` would leave dependents stale.
        let code1 = "# no exists\nx <- 1\nsource(\"child.R\")";
        let code2 = "exists(\"x\")\nx <- 1\nsource(\"child.R\")";
        let tree1 = parse_r(code1);
        let tree2 = parse_r(code2);
        let artifacts1 = compute_artifacts(&test_uri(), &tree1, code1);
        let artifacts2 = compute_artifacts(&test_uri(), &tree2, code2);

        assert_ne!(
            artifacts1.interface_hash, artifacts2.interface_hash,
            "interface_hash must change when an exists() declaration is added, even when a real def shadows it"
        );
    }

    #[test]
    fn test_interface_hash_unchanged_when_rm_inside_function_body() {
        // rm() inside a function body has no cross-file effect — the body
        // is delayed-evaluation and doesn't run at top level. Such rm()
        // calls must not perturb interface_hash, otherwise local edits to
        // function bodies would needlessly republish dependents.
        let code1 = "f <- function() { 1 }\ny <- 2";
        let code2 = "f <- function() { rm(z); 1 }\ny <- 2";
        let tree1 = parse_r(code1);
        let tree2 = parse_r(code2);
        let artifacts1 = compute_artifacts(&test_uri(), &tree1, code1);
        let artifacts2 = compute_artifacts(&test_uri(), &tree2, code2);

        // Note: function body contents typically don't show up in
        // interface_hash because exported_interface only lists top-level
        // symbols. The function `f` itself is unchanged either way. So we
        // assert the hash is stable to lock in that an in-body rm() never
        // contributes.
        assert_eq!(
            artifacts1.interface_hash, artifacts2.interface_hash,
            "rm() inside a function body must not change interface_hash"
        );
    }

    #[test]
    fn test_interface_hash_changes_when_data_call_package_arg_changes() {
        // A change ONLY in the `package =` argument of a top-level data() call
        // must change interface_hash. The literal stem `api` binds the same
        // `Def` symbol either way, so the `interface` contribution is byte-for-
        // byte identical between the two; the sole difference is the
        // `DataCallInfo.package` field. Query-time expansion (`expand_data_load`)
        // binds DIFFERENT objects depending on the package, which dependent
        // files see — so without folding `package` into the hash (issue #429),
        // cross-file revalidation would not fire on this edit and sourced files
        // would keep stale undefined-variable diagnostics. This test fails if
        // `package.hash()` is dropped from `compute_interface_hash`.
        let code1 = "data(api, package = \"survey\")\nsource(\"child.R\")";
        let code2 = "data(api, package = \"datasets\")\nsource(\"child.R\")";
        let tree1 = parse_r(code1);
        let tree2 = parse_r(code2);
        let artifacts1 = compute_artifacts(&test_uri(), &tree1, code1);
        let artifacts2 = compute_artifacts(&test_uri(), &tree2, code2);

        assert_ne!(
            artifacts1.interface_hash, artifacts2.interface_hash,
            "interface_hash must change when only the data() package= argument changes"
        );
    }

