    #[test]
    fn test_backward_directive_call_site_filtering() {
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::{BackwardDirective, CallSiteSpec, CrossFileMetadata};

        let parent_uri = Url::parse("file:///project/parent.R").unwrap();
        let child_uri = Url::parse("file:///project/child.R").unwrap();
        let workspace_root = Url::parse("file:///project").unwrap();

        // Parent code: a on line 0, x1 on line 1, source(child) on line 1 (implicit), x2 on line 2, y on line 3
        // We simulate parent sourcing child at line 1
        let parent_code = "a <- 1\nx1 <- 1\nx2 <- 2\ny <- 2";
        let parent_tree = parse_r(parent_code);
        let parent_artifacts = compute_artifacts(&parent_uri, &parent_tree, parent_code);

        // Verify parent artifacts
        println!("Parent timeline:");
        for event in &parent_artifacts.timeline {
            if let ScopeEvent::Def {
                line,
                column,
                symbol,
                ..
            } = event
            {
                println!("  Def: {} at ({}, {})", symbol.name, line, column);
            }
        }

        // Child with backward directive line=2 (1-based, so 0-based line 1)
        let child_code = "z <- 3";
        let child_tree = parse_r(child_code);
        let child_artifacts = compute_artifacts(&child_uri, &child_tree, child_code);

        let child_metadata = CrossFileMetadata {
            sourced_by: vec![BackwardDirective {
                path: "parent.R".to_string(),     // Same directory, no ../
                call_site: CallSiteSpec::Line(1), // 0-based line 1
                directive_line: 0,
            }],
            ..Default::default()
        };

        // Build dependency graph - the backward directive creates an edge from parent to child
        let mut graph = DependencyGraph::new();
        graph.update_file(
            &child_uri,
            &child_metadata,
            Some(&workspace_root),
            |parent_uri_check| {
                if parent_uri_check == &parent_uri {
                    Some(parent_code.to_string())
                } else {
                    None
                }
            },
        );

        let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
            if uri == &parent_uri {
                Some(Arc::new(parent_artifacts.clone()))
            } else if uri == &child_uri {
                Some(Arc::new(child_artifacts.clone()))
            } else {
                None
            }
        };

        let get_metadata = |uri: &Url| -> Option<std::sync::Arc<CrossFileMetadata>> {
            if uri == &child_uri {
                Some(std::sync::Arc::new(child_metadata.clone()))
            } else {
                None
            }
        };

        // Test scope at end of child file (line 0, after z definition)
        let scope = scope_at_position_with_graph(
            &child_uri,
            0,
            10,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Explicit,
            &|| false,
            None,
            None,
        );

        // Should have: a (from parent line 0), x1 (from parent line 1), z (local)
        // Should NOT have: x2 (parent line 2), y (parent line 3) - after call site
        assert!(
            scope.symbols.contains_key("a"),
            "Should have 'a' from parent"
        );
        assert!(
            scope.symbols.contains_key("x1"),
            "Should have 'x1' from parent"
        );
        assert!(
            scope.symbols.contains_key("z"),
            "Should have 'z' from local"
        );
        assert!(
            !scope.symbols.contains_key("x2"),
            "Should NOT have 'x2' - after call site"
        );
        assert!(
            !scope.symbols.contains_key("y"),
            "Should NOT have 'y' - after call site"
        );
    }

    #[test]
    fn backward_mode_filters_before_same_parent_invocation_grouping() {
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::{
            BackwardDirective, CallSiteSpec, CrossFileMetadata, ForwardSource,
        };

        let parent_uri = Url::parse("file:///project/parent.R").unwrap();
        let child_uri = Url::parse("file:///project/child.R").unwrap();
        let root = Url::parse("file:///project").unwrap();
        let parent_code = "early <- 1\nmiddle <- 2\nsource(\"child.R\")\nlate <- 3";
        let child_code = "child <- 1";
        let parent_artifacts = compute_artifacts(&parent_uri, &parse_r(parent_code), parent_code);
        let child_artifacts = compute_artifacts(&child_uri, &parse_r(child_code), child_code);
        let child_meta = CrossFileMetadata {
            sourced_by: vec![BackwardDirective {
                path: "parent.R".to_string(),
                call_site: CallSiteSpec::Line(0),
                directive_line: 0,
            }],
            ..Default::default()
        };
        let parent_meta = CrossFileMetadata {
            sources: vec![ForwardSource {
                path: "child.R".to_string(),
                line: 2,
                column: 0,
                ..Default::default()
            }],
            ..Default::default()
        };
        let mut graph = DependencyGraph::new();
        graph.update_file(&child_uri, &child_meta, Some(&root), |uri| {
            (uri == &parent_uri).then(|| parent_code.to_string())
        });
        graph.update_file(&parent_uri, &parent_meta, Some(&root), |_| None);

        let get_artifacts = |uri: &Url| {
            if uri == &parent_uri {
                Some(Arc::new(parent_artifacts.clone()))
            } else if uri == &child_uri {
                Some(Arc::new(child_artifacts.clone()))
            } else {
                None
            }
        };
        let get_metadata = |uri: &Url| {
            if uri == &parent_uri {
                Some(Arc::new(parent_meta.clone()))
            } else if uri == &child_uri {
                Some(Arc::new(child_meta.clone()))
            } else {
                None
            }
        };
        for mode in [
            crate::cross_file::config::BackwardDependencyMode::Explicit,
            crate::cross_file::config::BackwardDependencyMode::Auto,
        ] {
            let scope = scope_at_position_with_graph(
                &child_uri,
                u32::MAX,
                u32::MAX,
                &get_artifacts,
                &get_metadata,
                &graph,
                Some(&root),
                10,
                &HashSet::new(),
                false,
                mode,
                &|| false,
                None,
                None,
            );
            assert!(scope.symbols.contains_key("early"), "{mode:?}: {scope:?}");
            assert!(!scope.symbols.contains_key("middle"), "{mode:?}: {scope:?}");
            assert!(!scope.symbols.contains_key("late"), "{mode:?}: {scope:?}");
        }
    }

