    #[test]
    fn standalone_cache_interface_edit_to_closure_member_misses() {
        use crate::cross_file::standalone_cache::StandaloneScopeCache;
        let (root, leaf, hub, a, b) = standard_cache_files();
        let (mut arts, metas, graph) = build_cache_scenario(
            &root,
            &[
                (leaf.clone(), "leaf_fn <- function() 1\n"),
                (
                    hub.clone(),
                    "# raven: standalone\nsource(\"leaf.r\")\nhub_fn <- function() 2\n",
                ),
                (a.clone(), "source(\"hub.r\")\n"),
                (b.clone(), "source(\"hub.r\")\n"),
            ],
        );
        let cache = Arc::new(StandaloneScopeCache::new());
        let rev = graph.edge_revision();

        resolve_eof_cached(&a, &arts, &metas, &graph, &root, &cache, rev, 0);
        assert_eq!(cache.misses(), 1);

        // Add a top-level symbol to leaf → interface_hash changes → fingerprint
        // changes → cache MISS → recompute → the new symbol is now visible.
        replace_artifacts(
            &mut arts,
            &leaf,
            "leaf_fn <- function() 1\nleaf_fn2 <- function() 9\n",
        );
        let sb = resolve_eof_cached(&b, &arts, &metas, &graph, &root, &cache, rev, 0);
        assert_eq!(
            cache.hits(),
            0,
            "an interface edit must NOT hit the stale entry"
        );
        assert_eq!(cache.misses(), 2, "the interface edit recomputes");
        assert!(
            sb.symbols.contains_key("leaf_fn2"),
            "the recomputed scope reflects the closure member's new interface"
        );
    }

    #[test]
    fn standalone_cache_generation_bump_misses() {
        use crate::cross_file::standalone_cache::StandaloneScopeCache;
        let (root, leaf, hub, a, b) = standard_cache_files();
        let (arts, metas, graph) = build_cache_scenario(
            &root,
            &[
                (leaf.clone(), "leaf_fn <- function() 1\n"),
                (
                    hub.clone(),
                    "# raven: standalone\nsource(\"leaf.r\")\nhub_fn <- function() 2\n",
                ),
                (a.clone(), "source(\"hub.r\")\n"),
                (b.clone(), "source(\"hub.r\")\n"),
            ],
        );
        let cache = Arc::new(StandaloneScopeCache::new());
        let rev = graph.edge_revision();

        resolve_eof_cached(&a, &arts, &metas, &graph, &root, &cache, rev, 0);
        // A package_config_generation bump (e.g. R re-init) changes the key.
        resolve_eof_cached(&b, &arts, &metas, &graph, &root, &cache, rev, 1);
        assert_eq!(cache.hits(), 0, "a generation bump must invalidate the key");
        assert_eq!(cache.misses(), 2);
        // And an edge_revision bump likewise.
        resolve_eof_cached(&a, &arts, &metas, &graph, &root, &cache, rev + 1, 1);
        assert_eq!(
            cache.hits(),
            0,
            "an edge_revision bump must invalidate the key"
        );
        assert_eq!(cache.misses(), 3);
    }

    #[test]
    fn standalone_cache_hit_value_is_byte_identical_to_uncached() {
        use crate::cross_file::standalone_cache::StandaloneScopeCache;
        let (root, leaf, hub, a, b) = standard_cache_files();
        let (arts, metas, graph) = build_cache_scenario(
            &root,
            &[
                (leaf.clone(), "leaf_fn <- function() 1\nleaf_x <- 7\n"),
                (
                    hub.clone(),
                    "# raven: standalone\nsource(\"leaf.r\")\nhub_fn <- function() 2\n",
                ),
                (a.clone(), "source(\"hub.r\")\n"),
                (b.clone(), "source(\"hub.r\")\n"),
            ],
        );
        let get_artifacts = |u: &Url| arts.get(u).cloned();
        let get_metadata = |u: &Url| metas.get(u).cloned();
        // Uncached resolution of caller b (no standalone cache context).
        let uncached = scope_at_position_with_graph(
            &b,
            u32::MAX,
            u32::MAX,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&root),
            64,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            None,
            None,
        );
        // Warm the cache via caller a, then resolve b through the cache (HIT on hub).
        let cache = Arc::new(StandaloneScopeCache::new());
        let rev = graph.edge_revision();
        resolve_eof_cached(&a, &arts, &metas, &graph, &root, &cache, rev, 0);
        let cached = resolve_eof_cached(&b, &arts, &metas, &graph, &root, &cache, rev, 0);
        assert!(cache.hits() >= 1, "b must hit hub's cached scope");
        // The merged caller scope must match the uncached resolution across every
        // scope-carrying field, not just the symbol key set — a HIT that diverged
        // in package state (the failure mode found in WI2b review) or in a
        // symbol's resolved identity must be caught here.
        // Full per-symbol identity: every `ScopedSymbol` field a caller consumes
        // (position fields drive hover/go-to-definition ranges; `is_declared`
        // drives declared-vs-real precedence at cross-file merges), not just
        // name+source+line+kind/signature. A HIT diverging in any of these is
        // exactly the provenance drift this byte-identity gate must catch.
        #[allow(clippy::type_complexity)]
        fn symbol_identities(
            s: &ScopeAtPosition,
        ) -> Vec<(String, String, u32, u32, u32, bool, String)> {
            let mut v: Vec<(String, String, u32, u32, u32, bool, String)> = s
                .symbols
                .iter()
                .map(|(name, sym)| {
                    (
                        name.to_string(),
                        sym.source_uri.to_string(),
                        sym.defined_line,
                        sym.defined_column,
                        sym.defined_end_column,
                        sym.is_declared,
                        format!("{:?}|{:?}", sym.kind, sym.signature),
                    )
                })
                .collect();
            v.sort();
            v
        }
        fn sorted(set: &HashSet<String>) -> Vec<String> {
            let mut v: Vec<String> = set.iter().cloned().collect();
            v.sort();
            v
        }
        fn sorted_arc_str(set: &HashSet<Arc<str>>) -> Vec<String> {
            let mut v: Vec<String> = set.iter().map(|s| s.to_string()).collect();
            v.sort();
            v
        }
        // package_origins VALUES (the per-package origin-URI sets), not just the
        // keys — origins feed the same-file leak filter at cross-file merges.
        fn origins(m: &HashMap<String, HashSet<Arc<Url>>>) -> Vec<(String, Vec<String>)> {
            let mut v: Vec<(String, Vec<String>)> = m
                .iter()
                .map(|(k, set)| {
                    let mut urls: Vec<String> = set.iter().map(|u| u.to_string()).collect();
                    urls.sort();
                    (k.clone(), urls)
                })
                .collect();
            v.sort();
            v
        }
        fn vis(m: &HashMap<Url, (u32, u32)>) -> Vec<(String, u32, u32)> {
            let mut v: Vec<(String, u32, u32)> = m
                .iter()
                .map(|(u, (l, c))| (u.to_string(), *l, *c))
                .collect();
            v.sort();
            v
        }
        fn depths(v: &[(Url, u32, u32)]) -> Vec<(String, u32, u32)> {
            let mut out: Vec<(String, u32, u32)> =
                v.iter().map(|(u, l, c)| (u.to_string(), *l, *c)).collect();
            out.sort();
            out
        }
        fn chain_strs(v: &[Url]) -> Vec<String> {
            v.iter().map(|u| u.to_string()).collect()
        }
        assert_eq!(
            symbol_identities(&cached),
            symbol_identities(&uncached),
            "a cache HIT must yield the same symbols (name + source + line/column/end_column + is_declared + kind/signature)"
        );
        assert_eq!(
            sorted(&cached.inherited_packages),
            sorted(&uncached.inherited_packages),
            "inherited_packages must match uncached"
        );
        assert_eq!(
            sorted(&cached.loaded_packages),
            sorted(&uncached.loaded_packages),
            "loaded_packages must match uncached"
        );
        assert_eq!(
            origins(&cached.package_origins),
            origins(&uncached.package_origins),
            "package_origins (keys AND origin-URI sets) must match uncached"
        );
        // The remaining scope-carrying fields a cached scope also carries and
        // callers consume: chain order, per-file visible positions, the
        // parent-prefix-only symbol set, and depth-exceeded markers.
        assert_eq!(
            chain_strs(&cached.chain),
            chain_strs(&uncached.chain),
            "chain must match uncached (order included)"
        );
        assert_eq!(
            vis(&cached.visible_positions),
            vis(&uncached.visible_positions),
            "visible_positions must match uncached"
        );
        assert_eq!(
            sorted_arc_str(&cached.parent_prefix_symbol_names),
            sorted_arc_str(&uncached.parent_prefix_symbol_names),
            "parent_prefix_symbol_names must match uncached"
        );
        assert_eq!(
            depths(&cached.depth_exceeded),
            depths(&uncached.depth_exceeded),
            "depth_exceeded must match uncached"
        );
    }

    #[test]
    fn standalone_cache_not_poisoned_by_contaminated_resolution() {
        // Regression for the worldwide cache-on != cache-off bug: resolving a
        // closure member with hoisted (inside-function) references resolves the
        // standalone hub as a backward parent at EOF with the member already in
        // `visited`, short-circuiting the hub's `source(member)` and producing a
        // TRUNCATED hub scope. That truncated scope must never be cached and
        // served to a clean forward-child caller (which needs the full closure).
        use crate::cross_file::standalone_cache::StandaloneScopeCache;
        let root = Url::parse("file:///proj").unwrap();
        let leaf = Url::parse("file:///proj/leaf.r").unwrap();
        let hub = Url::parse("file:///proj/hub.r").unwrap();
        let caller = Url::parse("file:///proj/caller.r").unwrap();
        // leaf references `hub_fn` INSIDE a function body (so resolving leaf with
        // hoist_globals walks to hub at EOF). hub defines hub_fn and sources leaf.
        let (arts, metas, graph) = build_cache_scenario(
            &root,
            &[
                (
                    leaf.clone(),
                    "g <- function() hub_fn()\nleaf_fn <- function() 1\n",
                ),
                (
                    hub.clone(),
                    "# raven: standalone\nsource(\"leaf.r\")\nhub_fn <- function() 2\n",
                ),
                (caller.clone(), "source(\"hub.r\")\n"),
            ],
        );
        let cache = Arc::new(StandaloneScopeCache::new());
        let rev = graph.edge_revision();

        // Resolve leaf at an inside-function position with hoist_globals=true so
        // the backward walk queries hub at EOF with leaf in `visited`.
        let get_artifacts = |u: &Url| arts.get(u).cloned();
        let get_metadata = |u: &Url| metas.get(u).cloned();
        let ctx = crate::cross_file::standalone_cache::StandaloneCacheCtx {
            cache: cache.clone(),
            edge_revision: rev,
            package_config_generation: 0,
        };
        let mut prefix_cache = ParentPrefixCache::new();
        let _leaf_scope = scope_at_position_with_graph_cached_with_standalone_cache(
            &leaf,
            0,
            16, // inside g's body, at `hub_fn`
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&root),
            64,
            &HashSet::new(),
            true, // hoist_globals: forces parent query at EOF
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            &mut prefix_cache,
            None,
            None,
            Some(ctx),
        );
        // The contaminated resolution must NOT have stored a (truncated) hub
        // entry — otherwise the caller below would lose `leaf_fn`.
        assert_eq!(
            cache.len(),
            0,
            "a visited-contaminated hub resolution must not be cached"
        );

        // Now a clean forward-child caller resolves hub fully → sees leaf_fn.
        let scaller = resolve_eof_cached(&caller, &arts, &metas, &graph, &root, &cache, rev, 0);
        assert!(
            scaller.symbols.contains_key("leaf_fn") && scaller.symbols.contains_key("hub_fn"),
            "the caller must see the FULL hub closure (leaf_fn + hub_fn), proving \
             no poisoned/truncated entry was served; got: {:?}",
            scaller.symbols.keys().collect::<Vec<_>>()
        );
    }

    #[test]
    fn test_source_local_false_global_scope() {
        // Test that source() with local=FALSE makes symbols available (inherits_symbols() returns true)
        let source = ForwardSource {
            path: "child.R".to_string(),
            line: 0,
            column: 0,
            is_directive: false,
            chdir: false,
            is_sys_source: false,
            locality: SourceLocality::Global,
            ..Default::default()
        };

        assert!(
            source.inherits_symbols(),
            "source() with local=FALSE should inherit symbols"
        );

        // Test that such sources are included in timeline
        let code = "x <- 1\nsource(\"child.R\", local = FALSE)\ny <- 2";
        let tree = parse_r(code);
        let artifacts = compute_artifacts(&test_uri(), &tree, code);

        // Should have source event in timeline
        let source_events: Vec<_> = artifacts
            .timeline
            .iter()
            .filter_map(|e| match e {
                ScopeEvent::Source { source, .. } => Some(source),
                _ => None,
            })
            .collect();

        assert_eq!(source_events.len(), 1, "Should have one source event");
        assert!(
            source_events[0].locality == SourceLocality::Global,
            "Source should have local=FALSE"
        );
        assert!(
            source_events[0].inherits_symbols(),
            "Source should inherit symbols"
        );
    }

    #[test]
    fn test_source_local_true_not_inherited() {
        // source(local=TRUE) does not inherit symbols into the global scope, but the call site
        // should still be represented in the timeline so scope resolution can make symbols
        // available within the containing function scope.
        let source = ForwardSource {
            path: "child.R".to_string(),
            line: 0,
            column: 0,
            is_directive: false,
            locality: crate::cross_file::types::SourceLocality::CurrentFrame,
            chdir: false,
            is_sys_source: false,
            ..Default::default()
        };

        assert!(
            !source.inherits_symbols(),
            "source() with local=TRUE should NOT inherit symbols"
        );

        // Local=TRUE sources are included in the timeline
        let code = "x <- 1\nsource(\"child.R\", local = TRUE)\ny <- 2";
        let tree = parse_r(code);
        let artifacts = compute_artifacts(&test_uri(), &tree, code);

        let source_events: Vec<_> = artifacts
            .timeline
            .iter()
            .filter_map(|e| match e {
                ScopeEvent::Source { source, .. } => Some(source),
                _ => None,
            })
            .collect();

        assert_eq!(source_events.len(), 1, "Should have one source event");
        assert!(
            source_events[0].locality != SourceLocality::Global,
            "Source should have local=TRUE"
        );
    }

    #[test]
    fn test_scope_with_graph_local_source_stays_function_scoped() {
        use crate::cross_file::dependency::DependencyGraph;

        let parent_uri = Url::parse("file:///project/parent.R").unwrap();
        let child_uri = Url::parse("file:///project/child.R").unwrap();
        let workspace_root = Url::parse("file:///project").unwrap();

        let parent_code = r#"wrapper <- function() {
    local_only <- 1
    source("child.R", local = TRUE)
    child_var + local_only
}
outside_var <- 2"#;
        let parent_tree = parse_r(parent_code);
        let parent_artifacts = compute_artifacts(&parent_uri, &parent_tree, parent_code);
        let parent_meta = crate::cross_file::extract_metadata(parent_code);

        let child_code = "child_var <- 42";
        let child_tree = parse_r(child_code);
        let child_artifacts = compute_artifacts(&child_uri, &child_tree, child_code);

        let mut graph = DependencyGraph::new();
        graph.update_file(&parent_uri, &parent_meta, Some(&workspace_root), |_| None);

        let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
            if uri == &parent_uri {
                Some(Arc::new(parent_artifacts.clone()))
            } else if uri == &child_uri {
                Some(Arc::new(child_artifacts.clone()))
            } else {
                None
            }
        };

        let get_metadata =
            |uri: &Url| -> Option<std::sync::Arc<crate::cross_file::types::CrossFileMetadata>> {
                if uri == &parent_uri {
                    Some(std::sync::Arc::new(parent_meta.clone()))
                } else {
                    None
                }
            };

        let scope_inside_function = scope_at_position_with_graph(
            &parent_uri,
            3,
            10,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            None,
            None,
        );
        assert!(
            scope_inside_function.symbols.contains_key("child_var"),
            "child_var should be visible inside the function after source(local=TRUE)"
        );
        assert!(
            scope_inside_function.symbols.contains_key("local_only"),
            "local_only should stay visible inside the containing function"
        );

        // Query at end of `outside_var <- 2` so the binding is visible (R only
        // installs the LHS binding after the RHS finishes evaluating, so a
        // mid-assignment query position would correctly not yet see it).
        let scope_after_function = scope_at_position_with_graph(
            &parent_uri,
            5,
            16,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            None,
            None,
        );
        assert!(
            !scope_after_function.symbols.contains_key("child_var"),
            "child_var should not leak into outer scope after source(local=TRUE)"
        );
        assert!(
            !scope_after_function.symbols.contains_key("local_only"),
            "local_only should not be visible outside the function"
        );
        assert!(
            scope_after_function.symbols.contains_key("outside_var"),
            "outside_var should remain visible in outer scope"
        );
    }

    #[test]
    fn test_scope_with_graph_nonlocal_source_in_function_is_globally_visible() {
        use crate::cross_file::dependency::DependencyGraph;

        let parent_uri = Url::parse("file:///project/parent.R").unwrap();
        let child_uri = Url::parse("file:///project/child.R").unwrap();
        let workspace_root = Url::parse("file:///project").unwrap();

        // source() without local=TRUE inside a function — child symbols should be
        // globally visible (R's default behavior: source() evaluates in .GlobalEnv).
        let parent_code = r#"wrapper <- function() {
    fn_only <- 1
    source("child.R")
    child_var + fn_only
}
outside_var <- 2"#;
        let parent_tree = parse_r(parent_code);
        let parent_artifacts = compute_artifacts(&parent_uri, &parent_tree, parent_code);
        let parent_meta = crate::cross_file::extract_metadata(parent_code);

        let child_code = "child_var <- 42";
        let child_tree = parse_r(child_code);
        let child_artifacts = compute_artifacts(&child_uri, &child_tree, child_code);

        let mut graph = DependencyGraph::new();
        graph.update_file(&parent_uri, &parent_meta, Some(&workspace_root), |_| None);

        let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
            if uri == &parent_uri {
                Some(Arc::new(parent_artifacts.clone()))
            } else if uri == &child_uri {
                Some(Arc::new(child_artifacts.clone()))
            } else {
                None
            }
        };

        let get_metadata =
            |uri: &Url| -> Option<std::sync::Arc<crate::cross_file::types::CrossFileMetadata>> {
                if uri == &parent_uri {
                    Some(std::sync::Arc::new(parent_meta.clone()))
                } else {
                    None
                }
            };

        // Inside the function: child_var should be visible (source is before this point)
        let scope_inside_function = scope_at_position_with_graph(
            &parent_uri,
            3,
            10,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            None,
            None,
        );
        assert!(
            scope_inside_function.symbols.contains_key("child_var"),
            "child_var should be visible inside the function after non-local source()"
        );
        assert!(
            scope_inside_function.symbols.contains_key("fn_only"),
            "fn_only should be visible inside its defining function"
        );

        // Outside the function: child_var should still be visible (non-local source
        // evaluates in .GlobalEnv, so its symbols are globally available)
        // Query at end of `outside_var <- 2` so the binding is visible (R only
        // installs the LHS binding after the RHS finishes evaluating, so a
        // mid-assignment query position would correctly not yet see it).
        let scope_after_function = scope_at_position_with_graph(
            &parent_uri,
            5,
            16,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            None,
            None,
        );
        assert!(
            scope_after_function.symbols.contains_key("child_var"),
            "child_var should be visible in outer scope after non-local source()"
        );
        assert!(
            !scope_after_function.symbols.contains_key("fn_only"),
            "fn_only should not leak outside its defining function"
        );
        assert!(
            scope_after_function.symbols.contains_key("outside_var"),
            "outside_var should remain visible in outer scope"
        );
    }

    #[test]
    fn test_source_default_local_false() {
        // Test that source() without local parameter defaults to local=FALSE behavior
        let code = "x <- 1\nsource(\"child.R\")\ny <- 2";
        let tree = parse_r(code);
        let artifacts = compute_artifacts(&test_uri(), &tree, code);

        // Should have source event in timeline (defaults to local=FALSE)
        let source_events: Vec<_> = artifacts
            .timeline
            .iter()
            .filter_map(|e| match e {
                ScopeEvent::Source { source, .. } => Some(source),
                _ => None,
            })
            .collect();

        assert_eq!(source_events.len(), 1, "Should have one source event");
        assert!(
            source_events[0].locality == SourceLocality::Global,
            "Source should default to local=FALSE"
        );
        assert!(
            source_events[0].inherits_symbols(),
            "Source should inherit symbols by default"
        );
    }

    #[test]
    fn test_scope_at_position_with_graph() {
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::{CrossFileMetadata, ForwardSource};

        let parent_uri = Url::parse("file:///project/parent.R").unwrap();
        let child_uri = Url::parse("file:///project/child.R").unwrap();
        let workspace_root = Url::parse("file:///project").unwrap();

        // Parent code: defines 'a' then sources child
        let parent_code = "a <- 1\nsource(\"child.R\")";
        let parent_tree = parse_r(parent_code);
        let parent_artifacts = compute_artifacts(&parent_uri, &parent_tree, parent_code);

        // Child code: defines 'b'
        let child_code = "b <- 2";
        let child_tree = parse_r(child_code);
        let child_artifacts = compute_artifacts(&child_uri, &child_tree, child_code);

        // Build dependency graph
        let mut graph = DependencyGraph::new();
        let parent_meta = CrossFileMetadata {
            sources: vec![ForwardSource {
                path: "child.R".to_string(),
                line: 1,
                column: 0,
                is_directive: false,
                chdir: false,
                is_sys_source: false,
                ..Default::default()
            }],
            ..Default::default()
        };
        graph.update_file(&parent_uri, &parent_meta, Some(&workspace_root), |_| None);

        let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
            if uri == &parent_uri {
                Some(Arc::new(parent_artifacts.clone()))
            } else if uri == &child_uri {
                Some(Arc::new(child_artifacts.clone()))
            } else {
                None
            }
        };

        let get_metadata = |uri: &Url| -> Option<std::sync::Arc<CrossFileMetadata>> {
            if uri == &parent_uri {
                Some(std::sync::Arc::new(parent_meta.clone()))
            } else {
                None
            }
        };

        // At end of parent file, both 'a' and 'b' should be available
        let scope = scope_at_position_with_graph(
            &parent_uri,
            10,
            0,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Explicit,
            &|| false,
            None,
            None,
        );

        assert!(scope.symbols.contains_key("a"), "a should be available");
        assert!(
            scope.symbols.contains_key("b"),
            "b should be available from sourced file"
        );
    }

    #[test]
    fn non_lending_parent_does_not_lend_symbols_to_helper_scope() {
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::{CrossFileMetadata, ForwardSource};

        let excluded_uri = Url::parse("file:///project/excluded.R").unwrap();
        let helper_uri = Url::parse("file:///project/helper.R").unwrap();
        let workspace_root = Url::parse("file:///project").unwrap();

        let excluded_code = "from_excluded <- 1\nsource(\"helper.R\")\n";
        let helper_code = "from_helper <- 2\n";
        let excluded_artifacts = Arc::new(compute_artifacts(
            &excluded_uri,
            &parse_r(excluded_code),
            excluded_code,
        ));
        let helper_artifacts = Arc::new(compute_artifacts(
            &helper_uri,
            &parse_r(helper_code),
            helper_code,
        ));

        let mut graph = DependencyGraph::new();
        let excluded_meta = CrossFileMetadata {
            sources: vec![ForwardSource {
                path: "helper.R".to_string(),
                line: 1,
                column: 0,
                ..Default::default()
            }],
            ..Default::default()
        };
        graph.update_file(&excluded_uri, &excluded_meta, Some(&workspace_root), |_| {
            None
        });
        graph.make_forward_edges_non_lending(&excluded_uri);

        let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
            if uri == &excluded_uri {
                Some(excluded_artifacts.clone())
            } else if uri == &helper_uri {
                Some(helper_artifacts.clone())
            } else {
                None
            }
        };
        let get_metadata = |uri: &Url| -> Option<Arc<CrossFileMetadata>> {
            (uri == &excluded_uri).then(|| Arc::new(excluded_meta.clone()))
        };

        let helper_scope = scope_at_position_with_graph(
            &helper_uri,
            u32::MAX,
            u32::MAX,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            None,
            None,
        );

        assert!(
            !helper_scope.symbols.contains_key("from_excluded"),
            "a non-lending excluded parent must not contribute symbols to the helper"
        );
        assert!(
            helper_scope.symbols.contains_key("from_helper"),
            "the helper's own symbols remain visible"
        );
    }

