    #[test]
    fn test_cross_file_declared_symbols_inherited_with_local_true() {
        // Issue #476: a TOP-LEVEL source(local=TRUE) evaluates the child in
        // `.GlobalEnv`, so BOTH the parent's declared symbols AND its regular
        // top-level bindings are visible in the child — identical to local=FALSE.
        // Function-scoped CurrentFrame calls likewise inherit through their call
        // frame; only NonInheriting destinations remain declared-only.
        // This test asserts both: declared_var (always inherited) and regular_var
        // (the load-bearing #476 behavior — would FAIL under the pre-fix code).
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::{CrossFileMetadata, DeclaredSymbol, ForwardSource};

        let parent_uri = Url::parse("file:///project/parent.R").unwrap();
        let child_uri = Url::parse("file:///project/child.R").unwrap();
        let workspace_root = Url::parse("file:///project").unwrap();

        // Parent code: declares 'declared_var' via directive, defines 'regular_var',
        // then sources child with local=TRUE at line 2
        let parent_code =
            "# @lsp-var declared_var\nregular_var <- 1\nsource(\"child.R\", local = TRUE)";
        let parent_tree = parse_r(parent_code);
        let mut parent_artifacts = compute_artifacts(&parent_uri, &parent_tree, parent_code);

        // Add Declaration event for declared_var (simulating directive parsing)
        parent_artifacts.timeline.push(ScopeEvent::Declaration {
            line: 0,
            column: u32::MAX, // End-of-line sentinel
            symbol: ScopedSymbol {
                name: Arc::from("declared_var"),
                kind: SymbolKind::Variable,
                source_uri: parent_uri.clone(),
                defined_line: 0,
                defined_column: 0,
                defined_end_column: crate::utf16::utf16_len("declared_var"),
                signature: None,
                is_declared: true,
            },
            runtime_function_scope: RuntimeFunctionScope::Explicit(None),
            function_scope: None,
        });
        // Re-sort timeline
        parent_artifacts.timeline.sort_by_key(|event| match event {
            ScopeEvent::Def { line, column, .. } => (*line, *column),
            ScopeEvent::Source { line, column, .. } => (*line, *column),
            ScopeEvent::FunctionScope {
                start_line,
                start_column,
                ..
            } => (*start_line, *start_column),
            ScopeEvent::Removal { line, column, .. } => (*line, *column),
            ScopeEvent::PackageLoad { line, column, .. } => (*line, *column),
            ScopeEvent::DataLoad { line, column, .. } => (*line, *column),
            ScopeEvent::Declaration { line, column, .. } => (*line, *column),
        });

        // Child code: just a simple definition
        let child_code = "child_var <- 2";
        let child_tree = parse_r(child_code);
        let child_artifacts = compute_artifacts(&child_uri, &child_tree, child_code);

        // Build dependency graph with local=TRUE edge
        let mut graph = DependencyGraph::new();
        let parent_meta = CrossFileMetadata {
            sources: vec![ForwardSource {
                path: "child.R".to_string(),
                line: 2,
                column: 0,
                is_directive: false,
                locality: crate::cross_file::types::SourceLocality::CurrentFrame,
                chdir: false,
                is_sys_source: false,
                ..Default::default()
            }],
            declared_variables: vec![DeclaredSymbol {
                name: "declared_var".to_string(),
                line: 0,
                is_function: false,
                formals: None,
            }],
            ..Default::default()
        };
        graph.update_file(&parent_uri, &parent_meta, Some(&workspace_root), |_| None);

        let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
            if uri == &parent_uri {
                Some(Arc::new(parent_artifacts.clone()))
            } else if uri == &child_uri {
                Some(Arc::new(child_artifacts.clone()))
            } else {
                None
            }
        };

        let get_metadata = |uri: &Url| -> Option<std::sync::Arc<CrossFileMetadata>> {
            if uri == &parent_uri {
                Some(std::sync::Arc::new(parent_meta.clone()))
            } else {
                None
            }
        };

        // In the child file, BOTH declared_var and regular_var should be available.
        // Issue #476: a top-level source(local=TRUE) evaluates the child in
        // .GlobalEnv, so the parent's prior top-level bindings (regular AND declared)
        // are visible — identical to local=FALSE. CurrentFrame calls inside
        // functions inherit through the same call-frame chain.
        let scope = scope_at_position_with_graph(
            &child_uri,
            10,
            0,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            None,
            None,
        );

        assert!(
            scope.symbols.contains_key("declared_var"),
            "declared_var should be available from parent even with local=TRUE"
        );
        // Issue #476: a TOP-LEVEL `source(local = TRUE)` evaluates the child in
        // the caller's environment, which at top level is `.GlobalEnv` (R
        // `?source`). The child therefore sees the parent's prior top-level
        // bindings — regular AND declared — exactly like local=FALSE. Inside a
        // function, `local = TRUE` targets that call frame, which still inherits
        // the enclosing top-level environment.
        assert!(
            scope.symbols.contains_key("regular_var"),
            "regular_var SHOULD be available from a top-level parent with local=TRUE (issue #476)"
        );
        assert!(
            scope.symbols.contains_key("child_var"),
            "child_var should be available locally"
        );
    }

    #[test]
    fn bquote_external_source_retains_dependency_without_inheritance_or_lending() {
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::{CrossFileMetadata, SourceLocality};

        let parent_uri = Url::parse("file:///project/parent.R").unwrap();
        let child_uri = Url::parse("file:///project/child.R").unwrap();
        let workspace_root = Url::parse("file:///project").unwrap();
        let child_code = "child_only <- 2";
        let child_artifacts = compute_artifacts(&child_uri, &parse_r(child_code), child_code);

        let resolve_child = |source_call: &str| {
            let parent_code =
                format!("# raven: var declared_only\nparent_only <- 1\n{source_call}");
            let parent_meta = crate::cross_file::extract_metadata(&parent_code);
            let parent_artifacts = compute_artifacts_with_metadata(
                &parent_uri,
                &parse_r(&parent_code),
                &parent_code,
                Some(&parent_meta),
            );
            let mut graph = DependencyGraph::new();
            graph.update_file(&parent_uri, &parent_meta, Some(&workspace_root), |_| None);
            let dependencies = graph.get_dependencies(&parent_uri);
            assert_eq!(dependencies.len(), 1, "{parent_code}");
            let edge_locality = dependencies[0].locality;
            let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
                if uri == &parent_uri {
                    Some(Arc::new(parent_artifacts.clone()))
                } else if uri == &child_uri {
                    Some(Arc::new(child_artifacts.clone()))
                } else {
                    None
                }
            };
            let get_metadata = |uri: &Url| -> Option<Arc<CrossFileMetadata>> {
                (uri == &parent_uri).then(|| Arc::new(parent_meta.clone()))
            };
            let child_scope = scope_at_position_with_graph(
                &child_uri,
                u32::MAX,
                u32::MAX,
                &get_artifacts,
                &get_metadata,
                &graph,
                Some(&workspace_root),
                10,
                &HashSet::new(),
                false,
                crate::cross_file::config::BackwardDependencyMode::Auto,
                &|| false,
                None,
                None,
            );
            let parent_scope = scope_at_position_with_graph(
                &parent_uri,
                u32::MAX,
                u32::MAX,
                &get_artifacts,
                &get_metadata,
                &graph,
                Some(&workspace_root),
                10,
                &HashSet::new(),
                false,
                crate::cross_file::config::BackwardDependencyMode::Auto,
                &|| false,
                None,
                None,
            );
            (edge_locality, child_scope, parent_scope)
        };

        let (locality, caller_child, caller_parent) =
            resolve_child(r#"bquote(.(source("child.R", local = TRUE)), where = parent.frame())"#);
        assert_eq!(locality, SourceLocality::CurrentFrame);
        assert!(caller_child.symbols.contains_key("parent_only"));
        assert!(caller_child.symbols.contains_key("declared_only"));
        assert!(
            !caller_parent.symbols.contains_key("child_only"),
            "a caller-frame local source must not lend child bindings outward"
        );

        let (locality, external_child, external_parent) = resolve_child(
            r#"env <- base::new.env(parent = base::emptyenv())
base::bquote(.(source("child.R", local = TRUE)), where = env)"#,
        );
        assert_eq!(locality, SourceLocality::NonInheriting);
        assert!(external_child.symbols.contains_key("declared_only"));
        assert!(
            !external_child.symbols.contains_key("parent_only"),
            "a source evaluated in an environment with an empty parent must not inherit ordinary parent bindings"
        );
        assert!(
            !external_parent.symbols.contains_key("child_only"),
            "an external capture frame must not lend child bindings outward"
        );

        let (locality, global_child, global_parent) =
            resolve_child(r#"bquote(.(source("child.R", local = TRUE)), where = .GlobalEnv)"#);
        assert_eq!(locality, SourceLocality::Global);
        assert!(global_child.symbols.contains_key("parent_only"));
        assert!(global_child.symbols.contains_key("declared_only"));
        assert!(global_parent.symbols.contains_key("child_only"));
    }

    #[test]
    fn source_locality_controls_direct_inherited_and_sibling_packages() {
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::CrossFileMetadata;

        let root = Url::parse("file:///project").unwrap();
        let ancestor_uri = Url::parse("file:///project/ancestor.R").unwrap();
        let parent_uri = Url::parse("file:///project/parent.R").unwrap();
        let sibling_uri = Url::parse("file:///project/sibling.R").unwrap();
        let child_uri = Url::parse("file:///project/child.R").unwrap();
        let grandchild_uri = Url::parse("file:///project/grandchild.R").unwrap();

        let resolve = |source_call: &str| {
            let ancestor_code = "library(ancestorpkg)\nsource(\"parent.R\")";
            let parent_code = format!(
                "# raven: var declared\nparent_only <- 1\nlibrary(directpkg)\nsource(\"sibling.R\")\n{source_call}"
            );
            let sibling_code = "library(siblingpkg)";
            let child_code = "child_only <- 1\nlibrary(childpkg)\nsource(\"grandchild.R\")";
            let grandchild_code = "grandchild_only <- 1\nlibrary(grandchildpkg)";

            let ancestor_meta = crate::cross_file::extract_metadata(ancestor_code);
            let parent_meta = crate::cross_file::extract_metadata(&parent_code);
            let child_meta = crate::cross_file::extract_metadata(child_code);
            let ancestor_artifacts = compute_artifacts_with_metadata(
                &ancestor_uri,
                &parse_r(ancestor_code),
                ancestor_code,
                Some(&ancestor_meta),
            );
            let parent_artifacts = compute_artifacts_with_metadata(
                &parent_uri,
                &parse_r(&parent_code),
                &parent_code,
                Some(&parent_meta),
            );
            let sibling_artifacts =
                compute_artifacts(&sibling_uri, &parse_r(sibling_code), sibling_code);
            let child_artifacts = compute_artifacts_with_metadata(
                &child_uri,
                &parse_r(child_code),
                child_code,
                Some(&child_meta),
            );
            let grandchild_artifacts =
                compute_artifacts(&grandchild_uri, &parse_r(grandchild_code), grandchild_code);

            let mut graph = DependencyGraph::new();
            graph.update_file(&ancestor_uri, &ancestor_meta, Some(&root), |_| None);
            graph.update_file(&parent_uri, &parent_meta, Some(&root), |_| None);
            graph.update_file(&child_uri, &child_meta, Some(&root), |_| None);

            let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
                if uri == &ancestor_uri {
                    Some(Arc::new(ancestor_artifacts.clone()))
                } else if uri == &parent_uri {
                    Some(Arc::new(parent_artifacts.clone()))
                } else if uri == &sibling_uri {
                    Some(Arc::new(sibling_artifacts.clone()))
                } else if uri == &child_uri {
                    Some(Arc::new(child_artifacts.clone()))
                } else if uri == &grandchild_uri {
                    Some(Arc::new(grandchild_artifacts.clone()))
                } else {
                    None
                }
            };
            let get_metadata = |uri: &Url| -> Option<Arc<CrossFileMetadata>> {
                if uri == &ancestor_uri {
                    Some(Arc::new(ancestor_meta.clone()))
                } else if uri == &parent_uri {
                    Some(Arc::new(parent_meta.clone()))
                } else if uri == &child_uri {
                    Some(Arc::new(child_meta.clone()))
                } else {
                    None
                }
            };
            let query = |uri: &Url, line: u32, column: u32| {
                scope_at_position_with_graph(
                    uri,
                    line,
                    column,
                    &get_artifacts,
                    &get_metadata,
                    &graph,
                    Some(&root),
                    10,
                    &HashSet::new(),
                    false,
                    crate::cross_file::config::BackwardDependencyMode::Auto,
                    &|| false,
                    None,
                    None,
                )
            };
            let source_edge = graph
                .get_dependencies(&parent_uri)
                .into_iter()
                .find(|edge| edge.to == child_uri)
                .expect("parent must source child");
            let source_line = source_edge.call_site_line.unwrap();
            let source_column = source_edge.call_site_column.unwrap();
            (
                query(&child_uri, u32::MAX, u32::MAX),
                query(&grandchild_uri, u32::MAX, u32::MAX),
                query(&parent_uri, source_line, source_column),
                query(&parent_uri, source_line, source_column.saturating_add(1)),
            )
        };

        for source_call in [
            r#"source("child.R")"#,
            r#"bquote(.(source("child.R", local = TRUE)), where = parent.frame())"#,
        ] {
            let (child, grandchild, _, _) = resolve(source_call);
            for scope in [&child, &grandchild] {
                for package in ["ancestorpkg", "directpkg", "siblingpkg"] {
                    assert!(
                        scope.inherited_packages.contains(package)
                            || scope.loaded_packages.contains(package),
                        "{source_call}: missing {package}: {scope:?}"
                    );
                }
            }
            assert!(child.symbols.contains_key("declared"));
        }

        let (child, grandchild, parent_before, parent_after) = resolve(
            r#"env <- base::new.env(parent = base::emptyenv())
base::bquote(.(source("child.R", local = TRUE)), where = env)"#,
        );
        for scope in [&child, &grandchild] {
            for package in ["ancestorpkg", "directpkg", "siblingpkg"] {
                assert!(
                    !scope.inherited_packages.contains(package)
                        && !scope.loaded_packages.contains(package),
                    "NonInheriting leaked incoming {package}: {scope:?}"
                );
            }
            assert!(
                !scope.symbols.contains_key("parent_only"),
                "NonInheriting leaked an ordinary caller binding: {scope:?}"
            );
        }
        assert!(child.symbols.contains_key("declared"));
        assert!(child.loaded_packages.contains("childpkg"));
        assert!(child.loaded_packages.contains("grandchildpkg"));
        assert!(grandchild.loaded_packages.contains("grandchildpkg"));
        assert!(
            grandchild.inherited_packages.contains("childpkg")
                || grandchild.loaded_packages.contains("childpkg")
        );
        for package in ["childpkg", "grandchildpkg"] {
            assert!(
                !parent_before.loaded_packages.contains(package),
                "{package} must not be visible before the NonInheriting source call"
            );
            assert!(
                parent_after.loaded_packages.contains(package),
                "{package} attached by the child closure must be visible after the call"
            );
        }
        for symbol in ["child_only", "grandchild_only"] {
            assert!(
                !parent_after.symbols.contains_key(symbol),
                "NonInheriting source leaked child symbol {symbol}"
            );
        }
    }

    #[test]
    fn test_cross_file_declared_symbols_position_aware() {
        // Requirements 9.1, 9.2: Declared symbols follow position-based inheritance.
        // Only declarations before the source() call are available in the child.
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::{CrossFileMetadata, DeclaredSymbol, ForwardSource};

        let parent_uri = Url::parse("file:///project/parent.R").unwrap();
        let child_uri = Url::parse("file:///project/child.R").unwrap();
        let workspace_root = Url::parse("file:///project").unwrap();

        // Parent code: declares 'before_var' at line 0, sources child at line 1,
        // declares 'after_var' at line 2
        let parent_code = "# @lsp-var before_var\nsource(\"child.R\")\n# @lsp-var after_var";
        let parent_tree = parse_r(parent_code);
        let mut parent_artifacts = compute_artifacts(&parent_uri, &parent_tree, parent_code);

        // Add Declaration events
        parent_artifacts.timeline.push(ScopeEvent::Declaration {
            line: 0,
            column: u32::MAX,
            symbol: ScopedSymbol {
                name: Arc::from("before_var"),
                kind: SymbolKind::Variable,
                source_uri: parent_uri.clone(),
                defined_line: 0,
                defined_column: 0,
                defined_end_column: crate::utf16::utf16_len("before_var"),
                signature: None,
                is_declared: true,
            },
            runtime_function_scope: RuntimeFunctionScope::Explicit(None),
            function_scope: None,
        });
        parent_artifacts.timeline.push(ScopeEvent::Declaration {
            line: 2,
            column: u32::MAX,
            symbol: ScopedSymbol {
                name: Arc::from("after_var"),
                kind: SymbolKind::Variable,
                source_uri: parent_uri.clone(),
                defined_line: 2,
                defined_column: 0,
                defined_end_column: crate::utf16::utf16_len("after_var"),
                signature: None,
                is_declared: true,
            },
            runtime_function_scope: RuntimeFunctionScope::Explicit(None),
            function_scope: None,
        });
        // Re-sort timeline
        parent_artifacts.timeline.sort_by_key(|event| match event {
            ScopeEvent::Def { line, column, .. } => (*line, *column),
            ScopeEvent::Source { line, column, .. } => (*line, *column),
            ScopeEvent::FunctionScope {
                start_line,
                start_column,
                ..
            } => (*start_line, *start_column),
            ScopeEvent::Removal { line, column, .. } => (*line, *column),
            ScopeEvent::PackageLoad { line, column, .. } => (*line, *column),
            ScopeEvent::DataLoad { line, column, .. } => (*line, *column),
            ScopeEvent::Declaration { line, column, .. } => (*line, *column),
        });

        // Child code
        let child_code = "child_var <- 1";
        let child_tree = parse_r(child_code);
        let child_artifacts = compute_artifacts(&child_uri, &child_tree, child_code);

        // Build dependency graph
        let mut graph = DependencyGraph::new();
        let parent_meta = CrossFileMetadata {
            sources: vec![ForwardSource {
                path: "child.R".to_string(),
                line: 1,
                column: 0,
                is_directive: false,
                chdir: false,
                is_sys_source: false,
                ..Default::default()
            }],
            declared_variables: vec![
                DeclaredSymbol {
                    name: "before_var".to_string(),
                    line: 0,
                    is_function: false,
                    formals: None,
                },
                DeclaredSymbol {
                    name: "after_var".to_string(),
                    line: 2,
                    is_function: false,
                    formals: None,
                },
            ],
            ..Default::default()
        };
        graph.update_file(&parent_uri, &parent_meta, Some(&workspace_root), |_| None);

        let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
            if uri == &parent_uri {
                Some(Arc::new(parent_artifacts.clone()))
            } else if uri == &child_uri {
                Some(Arc::new(child_artifacts.clone()))
            } else {
                None
            }
        };

        let get_metadata = |uri: &Url| -> Option<std::sync::Arc<CrossFileMetadata>> {
            if uri == &parent_uri {
                Some(std::sync::Arc::new(parent_meta.clone()))
            } else {
                None
            }
        };

        // In child file:
        // - before_var should be available (declared before source() call) - Requirement 9.1
        // - after_var should NOT be available (declared after source() call) - Requirement 9.2
        let scope = scope_at_position_with_graph(
            &child_uri,
            10,
            0,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            None,
            None,
        );

        assert!(
            scope.symbols.contains_key("before_var"),
            "before_var should be available (declared before source() call) - Requirement 9.1"
        );
        assert!(
            !scope.symbols.contains_key("after_var"),
            "after_var should NOT be available (declared after source() call) - Requirement 9.2"
        );
    }

    #[test]
    fn test_max_depth_exceeded_backward() {
        // Test that depth_exceeded is populated when max depth is hit on backward directives
        use super::super::types::{CrossFileMetadata, ForwardSource};
        use crate::cross_file::dependency::DependencyGraph;

        let uri_a = Url::parse("file:///project/a.R").unwrap();
        let uri_b = Url::parse("file:///project/b.R").unwrap();
        let uri_c = Url::parse("file:///project/c.R").unwrap();
        let workspace_root = Url::parse("file:///project").unwrap();

        // c.R is sourced by b.R, b.R is sourced by a.R
        let code_a = "a_var <- 1\nsource(\"b.R\")";
        let code_b = "b_var <- 2\nsource(\"c.R\")";
        let code_c = "c_var <- 3";

        let tree_a = parse_r(code_a);
        let tree_b = parse_r(code_b);
        let tree_c = parse_r(code_c);

        let artifacts_a = compute_artifacts(&uri_a, &tree_a, code_a);
        let artifacts_b = compute_artifacts(&uri_b, &tree_b, code_b);
        let artifacts_c = compute_artifacts(&uri_c, &tree_c, code_c);

        // Build dependency graph
        let mut graph = DependencyGraph::new();
        let meta_a = CrossFileMetadata {
            sources: vec![ForwardSource {
                path: "b.R".to_string(),
                line: 1,
                column: 0,
                is_directive: false,
                chdir: false,
                is_sys_source: false,
                ..Default::default()
            }],
            ..Default::default()
        };
        let meta_b = CrossFileMetadata {
            sources: vec![ForwardSource {
                path: "c.R".to_string(),
                line: 1,
                column: 0,
                is_directive: false,
                chdir: false,
                is_sys_source: false,
                ..Default::default()
            }],
            ..Default::default()
        };

        graph.update_file(&uri_a, &meta_a, Some(&workspace_root), |_| None);
        graph.update_file(&uri_b, &meta_b, Some(&workspace_root), |_| None);

        let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
            if uri == &uri_a {
                Some(Arc::new(artifacts_a.clone()))
            } else if uri == &uri_b {
                Some(Arc::new(artifacts_b.clone()))
            } else if uri == &uri_c {
                Some(Arc::new(artifacts_c.clone()))
            } else {
                None
            }
        };

        let get_metadata = |uri: &Url| -> Option<std::sync::Arc<CrossFileMetadata>> {
            if uri == &uri_a {
                Some(std::sync::Arc::new(meta_a.clone()))
            } else if uri == &uri_b {
                Some(std::sync::Arc::new(meta_b.clone()))
            } else {
                None
            }
        };

        // With max_depth=2, traversing c->b->a should exceed
        let scope = scope_at_position_with_graph(
            &uri_c,
            u32::MAX,
            u32::MAX,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            2,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            None,
            None,
        );

        // Should have depth_exceeded entry
        assert!(
            !scope.depth_exceeded.is_empty(),
            "depth_exceeded should not be empty with max_depth=2"
        );
    }

    #[test]
    fn test_chdir_affects_nested_path_resolution() {
        // Test that chdir=TRUE causes child's relative paths to resolve from child's directory
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::{CrossFileMetadata, ForwardSource};

        // Directory structure:
        // /project/main.R - sources data/loader.R with chdir=TRUE
        // /project/data/loader.R - sources helpers.R (relative to data/)
        // /project/data/helpers.R - defines helper_func
        let main_uri = Url::parse("file:///project/main.R").unwrap();
        let loader_uri = Url::parse("file:///project/data/loader.R").unwrap();
        let helpers_uri = Url::parse("file:///project/data/helpers.R").unwrap();
        let workspace_root = Url::parse("file:///project").unwrap();

        // main.R: sources data/loader.R with chdir=TRUE
        let main_code = "x <- 1\nsource(\"data/loader.R\", chdir = TRUE)";
        let main_tree = parse_r(main_code);
        let main_artifacts = compute_artifacts(&main_uri, &main_tree, main_code);

        // loader.R: sources helpers.R (relative path)
        let loader_code = "source(\"helpers.R\")\nloader_var <- 1";
        let loader_tree = parse_r(loader_code);
        let loader_artifacts = compute_artifacts(&loader_uri, &loader_tree, loader_code);

        // helpers.R: defines helper_func
        let helpers_code = "helper_func <- function() {}";
        let helpers_tree = parse_r(helpers_code);
        let helpers_artifacts = compute_artifacts(&helpers_uri, &helpers_tree, helpers_code);

        // Build dependency graph
        let mut graph = DependencyGraph::new();
        let main_meta = CrossFileMetadata {
            sources: vec![ForwardSource {
                path: "data/loader.R".to_string(),
                line: 1,
                column: 0,
                is_directive: false,
                chdir: true, // chdir=TRUE
                is_sys_source: false,
                ..Default::default()
            }],
            ..Default::default()
        };
        let loader_meta = CrossFileMetadata {
            sources: vec![ForwardSource {
                path: "helpers.R".to_string(),
                line: 0,
                column: 0,
                is_directive: false,
                chdir: false,
                is_sys_source: false,
                ..Default::default()
            }],
            ..Default::default()
        };

        graph.update_file(&main_uri, &main_meta, Some(&workspace_root), |_| None);
        graph.update_file(&loader_uri, &loader_meta, Some(&workspace_root), |_| None);

        let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
            if uri == &main_uri {
                Some(Arc::new(main_artifacts.clone()))
            } else if uri == &loader_uri {
                Some(Arc::new(loader_artifacts.clone()))
            } else if uri == &helpers_uri {
                Some(Arc::new(helpers_artifacts.clone()))
            } else {
                None
            }
        };

        let get_metadata = |uri: &Url| -> Option<std::sync::Arc<CrossFileMetadata>> {
            if uri == &main_uri {
                Some(std::sync::Arc::new(main_meta.clone()))
            } else if uri == &loader_uri {
                Some(std::sync::Arc::new(loader_meta.clone()))
            } else {
                None
            }
        };

        // At end of main.R, helper_func should be available because:
        // 1. main.R sources data/loader.R with chdir=TRUE
        // 2. loader.R's working directory becomes /project/data/
        // 3. loader.R sources "helpers.R" which resolves to /project/data/helpers.R
        let scope = scope_at_position_with_graph(
            &main_uri,
            u32::MAX,
            u32::MAX,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Explicit,
            &|| false,
            None,
            None,
        );

        assert!(scope.symbols.contains_key("x"), "x should be available");
        assert!(
            scope.symbols.contains_key("loader_var"),
            "loader_var should be available from loader.R"
        );
        assert!(
            scope.symbols.contains_key("helper_func"),
            "helper_func should be available from helpers.R via chdir"
        );
    }

    #[test]
