    #[test]
    fn test_removal_event_sorting_by_position() {
        // Test that Removal events are correctly sorted by (line, column) position
        let mut events = [
            ScopeEvent::Removal {
                line: 5,
                column: 10,
                symbols: vec!["c".to_string()],
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
            ScopeEvent::Removal {
                line: 2,
                column: 0,
                symbols: vec!["a".to_string()],
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
            ScopeEvent::Removal {
                line: 5,
                column: 5,
                symbols: vec!["b".to_string()],
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
            ScopeEvent::Removal {
                line: 10,
                column: 0,
                symbols: vec!["d".to_string()],
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
        ];

        // Sort using the same key as compute_artifacts
        // Sort by each event's *effect* position so test ordering matches the
        // production timeline sort (Def events use `visible_from_*`, all others
        // use their own anchor). See `event_effect_position`.
        events.sort_by_key(event_effect_position);

        // Verify order: (2,0), (5,5), (5,10), (10,0)
        let positions: Vec<(u32, u32)> = events
            .iter()
            .map(|e| match e {
                ScopeEvent::Removal { line, column, .. } => (*line, *column),
                _ => panic!("Expected Removal event"),
            })
            .collect();

        assert_eq!(positions, vec![(2, 0), (5, 5), (5, 10), (10, 0)]);
    }

