    #[test]
    fn test_removal_event_mixed_with_def_events() {
        // Test that Removal events sort correctly when mixed with Def events
        let uri = test_uri();
        let mut events = [
            ScopeEvent::Removal {
                line: 3,
                column: 0,
                symbols: vec!["x".to_string()],
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
            ScopeEvent::Def {
                line: 1,
                column: 0,
                visible_from_line: 1,
                visible_from_column: 0,
                symbol: ScopedSymbol {
                    name: Arc::from("x"),
                    kind: SymbolKind::Variable,
                    source_uri: uri.clone(),
                    defined_line: 1,
                    defined_column: 0,
                    defined_end_column: crate::utf16::utf16_len("x"),
                    signature: None,
                    is_declared: false,
                },
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
            ScopeEvent::Def {
                line: 5,
                column: 0,
                visible_from_line: 5,
                visible_from_column: 0,
                symbol: ScopedSymbol {
                    name: Arc::from("y"),
                    kind: SymbolKind::Variable,
                    source_uri: uri.clone(),
                    defined_line: 5,
                    defined_column: 0,
                    defined_end_column: crate::utf16::utf16_len("y"),
                    signature: None,
                    is_declared: false,
                },
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
        ];

        // Sort by each event's *effect* position so test ordering matches the
        // production timeline sort (Def events use `visible_from_*`, all others
        // use their own anchor). See `event_effect_position`.
        events.sort_by_key(event_effect_position);

        // Verify order: Def(1,0), Removal(3,0), Def(5,0)
        let event_types: Vec<&str> = events
            .iter()
            .map(|e| match e {
                ScopeEvent::Def { .. } => "Def",
                ScopeEvent::Removal { .. } => "Removal",
                _ => "Other",
            })
            .collect();

        assert_eq!(event_types, vec!["Def", "Removal", "Def"]);

        // Verify positions
        let positions: Vec<(u32, u32)> = events
            .iter()
            .map(|e| match e {
                ScopeEvent::Def { line, column, .. } => (*line, *column),
                ScopeEvent::Removal { line, column, .. } => (*line, *column),
                _ => (0, 0),
            })
            .collect();

        assert_eq!(positions, vec![(1, 0), (3, 0), (5, 0)]);
    }

    #[test]
    fn test_removal_event_mixed_with_source_events() {
        // Test that Removal events sort correctly when mixed with Source events
        use super::super::types::ForwardSource;

        let mut events = [
            ScopeEvent::Removal {
                line: 2,
                column: 0,
                symbols: vec!["x".to_string()],
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
            ScopeEvent::Source {
                line: 1,
                column: 0,
                source: ForwardSource {
                    path: "child.R".to_string(),
                    line: 1,
                    column: 0,
                    is_directive: false,
                    chdir: false,
                    is_sys_source: false,
                    ..Default::default()
                },
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
            ScopeEvent::Removal {
                line: 4,
                column: 0,
                symbols: vec!["y".to_string()],
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
        ];

        // Sort by each event's *effect* position so test ordering matches the
        // production timeline sort (Def events use `visible_from_*`, all others
        // use their own anchor). See `event_effect_position`.
        events.sort_by_key(event_effect_position);

        // Verify order: Source(1,0), Removal(2,0), Removal(4,0)
        let event_types: Vec<&str> = events
            .iter()
            .map(|e| match e {
                ScopeEvent::Source { .. } => "Source",
                ScopeEvent::Removal { .. } => "Removal",
                _ => "Other",
            })
            .collect();

        assert_eq!(event_types, vec!["Source", "Removal", "Removal"]);
    }

    #[test]
    fn test_removal_event_mixed_with_all_event_types() {
        // Test that Removal events sort correctly when mixed with Def, Source, and FunctionScope events
        use super::super::types::ForwardSource;

        let uri = test_uri();
        let mut events = [
            ScopeEvent::Removal {
                line: 5,
                column: 0,
                symbols: vec!["z".to_string()],
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
            ScopeEvent::Def {
                line: 1,
                column: 0,
                visible_from_line: 1,
                visible_from_column: 0,
                symbol: ScopedSymbol {
                    name: Arc::from("x"),
                    kind: SymbolKind::Variable,
                    source_uri: uri.clone(),
                    defined_line: 1,
                    defined_column: 0,
                    defined_end_column: crate::utf16::utf16_len("x"),
                    signature: None,
                    is_declared: false,
                },
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
            ScopeEvent::Source {
                line: 3,
                column: 0,
                source: ForwardSource {
                    path: "child.R".to_string(),
                    line: 3,
                    column: 0,
                    is_directive: false,
                    chdir: false,
                    is_sys_source: false,
                    ..Default::default()
                },
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
            ScopeEvent::FunctionScope {
                start_line: 7,
                start_column: 0,
                end_line: 10,
                end_column: 1,
                parameters: vec![],
            },
            ScopeEvent::Removal {
                line: 9,
                column: 0,
                symbols: vec!["w".to_string()],
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
        ];

        // Sort by each event's *effect* position so test ordering matches the
        // production timeline sort (Def events use `visible_from_*`, all others
        // use their own anchor). See `event_effect_position`.
        events.sort_by_key(event_effect_position);

        // Verify order: Def(1,0), Source(3,0), Removal(5,0), FunctionScope(7,0), Removal(9,0)
        let event_types: Vec<&str> = events
            .iter()
            .map(|e| match e {
                ScopeEvent::Def { .. } => "Def",
                ScopeEvent::Source { .. } => "Source",
                ScopeEvent::FunctionScope { .. } => "FunctionScope",
                ScopeEvent::Removal { .. } => "Removal",
                ScopeEvent::PackageLoad { .. } => "PackageLoad",
                ScopeEvent::DataLoad { .. } => "DataLoad",
                ScopeEvent::Declaration { .. } => "Declaration",
            })
            .collect();

        assert_eq!(
            event_types,
            vec!["Def", "Source", "Removal", "FunctionScope", "Removal"]
        );

        // Verify positions
        let positions: Vec<u32> = events
            .iter()
            .map(|e| match e {
                ScopeEvent::Def { line, .. } => *line,
                ScopeEvent::Source { line, .. } => *line,
                ScopeEvent::FunctionScope { start_line, .. } => *start_line,
                ScopeEvent::Removal { line, .. } => *line,
                ScopeEvent::PackageLoad { line, .. } => *line,
                ScopeEvent::DataLoad { line, .. } => *line,
                ScopeEvent::Declaration { line, .. } => *line,
            })
            .collect();

        assert_eq!(positions, vec![1, 3, 5, 7, 9]);
    }

    #[test]
    fn test_removal_event_at_same_position_as_def() {
        // Test sorting when Removal and Def events are at the same position
        // (This is an edge case - in practice they would be at different positions)
        let uri = test_uri();
        let mut events = vec![
            ScopeEvent::Removal {
                line: 2,
                column: 0,
                symbols: vec!["x".to_string()],
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
            ScopeEvent::Def {
                line: 2,
                column: 0,
                visible_from_line: 2,
                visible_from_column: 0,
                symbol: ScopedSymbol {
                    name: Arc::from("y"),
                    kind: SymbolKind::Variable,
                    source_uri: uri.clone(),
                    defined_line: 2,
                    defined_column: 0,
                    defined_end_column: crate::utf16::utf16_len("y"),
                    signature: None,
                    is_declared: false,
                },
                runtime_function_scope: RuntimeFunctionScope::Lexical,
                function_scope: None,
            },
        ];

        // Sort by each event's *effect* position so test ordering matches the
        // production timeline sort (Def events use `visible_from_*`, all others
        // use their own anchor). See `event_effect_position`.
        events.sort_by_key(event_effect_position);

        // Both events should be at position (2, 0) - order between them is stable but not guaranteed
        // The important thing is that both are present and at the same position
        assert_eq!(events.len(), 2);
        for event in &events {
            let pos = match event {
                ScopeEvent::Def { line, column, .. } => (*line, *column),
                ScopeEvent::Removal { line, column, .. } => (*line, *column),
                _ => panic!("Unexpected event type"),
            };
            assert_eq!(pos, (2, 0));
        }
    }

    #[test]
    fn test_removal_event_clone() {
        // Test that Removal events can be cloned (derives Clone)
        let original = ScopeEvent::Removal {
            line: 5,
            column: 10,
            symbols: vec!["x".to_string(), "y".to_string()],
            runtime_function_scope: RuntimeFunctionScope::Lexical,
            function_scope: None,
        };

        let cloned = original.clone();

        match (original, cloned) {
            (
                ScopeEvent::Removal {
                    line: l1,
                    column: c1,
                    symbols: s1,
                    ..
                },
                ScopeEvent::Removal {
                    line: l2,
                    column: c2,
                    symbols: s2,
                    ..
                },
            ) => {
                assert_eq!(l1, l2);
                assert_eq!(c1, c2);
                assert_eq!(s1, s2);
            }
            _ => panic!("Expected Removal events"),
        }
    }

