    /// Regression: a symbol defined in an earlier-sourced sibling must stay
    /// visible in a later-sourced sibling even when a *hub* file, shared by the
    /// queried file's grandparent and another script, makes the parent prefix's
    /// backward walk reach the parent again at the EOF sentinel.
    ///
    /// Core graph: `data.r` sources `covariates.r` (defines `ww.covars`) then
    /// `indices.r` (uses `ww.covars`). The bug needs a deep parent walk: a
    /// shared hub (`functions.r`) is sourced by both `main.r` (which sources the
    /// hub *then* `data.r`) and `D.r` (which sources `data.r` *then* the hub).
    /// When `indices.r`'s parent prefix queries `data.r`, that frame's backward
    /// walk runs `main.r → functions.r → {functions.r's dependents} → D.r`,
    /// whose own forward sweep re-enters `data.r` at EOF and expands
    /// `covariates.r` into the shared `visited` map. `data.r`'s own STEP 2
    /// forward-source of `covariates.r` then hits the revisit guard and returns
    /// an empty scope, dropping `ww.covars`. Each parent frame's forward sources
    /// must be isolated from that frame's own backward walk, exactly like the
    /// queried file's are. See the `isolate_forward_source_visits = true`
    /// argument in `parent_prefix_at`'s recursive call.
    #[test]
    fn sibling_source_symbol_visible_through_shared_hub_parent_walk() {
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::CrossFileMetadata;

        let workspace_root = Url::parse("file:///project").unwrap();
        let main_uri = Url::parse("file:///project/main.r").unwrap();
        let d_uri = Url::parse("file:///project/scripts/D.r").unwrap();
        let functions_uri = Url::parse("file:///project/scripts/functions.r").unwrap();
        let data_uri = Url::parse("file:///project/scripts/data.r").unwrap();
        let covariates_uri = Url::parse("file:///project/scripts/data/covariates.r").unwrap();
        let indices_uri = Url::parse("file:///project/scripts/data/indices.r").unwrap();

        // Source paths are written relative to each sourcing file's directory so
        // the graph edges resolve directly (this helper's `update_file` does not
        // apply the workspace-root fallback). The orderings matter: `main.r`
        // sources the hub before `data.r`; `D.r` sources `data.r` before the hub.
        let main_code = "source(\"scripts/functions.r\")\nsource(\"scripts/data.r\")\n";
        let d_code = "source(\"data.r\")\nsource(\"functions.r\")\n";
        let functions_code = "helper <- function() 1\n";
        let data_code = "source(\"data/covariates.r\")\nsource(\"data/indices.r\")\n";
        let covariates_code = "ww.covars <- data.frame(year = 2024)\n";
        let indices_code = "y <- ww.covars$year\n";

        let files: [(&Url, &str); 6] = [
            (&main_uri, main_code),
            (&d_uri, d_code),
            (&functions_uri, functions_code),
            (&data_uri, data_code),
            (&covariates_uri, covariates_code),
            (&indices_uri, indices_code),
        ];

        let mut artifacts: HashMap<Url, Arc<ScopeArtifacts>> = HashMap::new();
        let mut metas: HashMap<Url, std::sync::Arc<CrossFileMetadata>> = HashMap::new();
        let mut graph = DependencyGraph::new();
        for (uri, code) in files {
            let tree = parse_r(code);
            artifacts.insert(
                (*uri).clone(),
                Arc::new(compute_artifacts(uri, &tree, code)),
            );
            let meta = std::sync::Arc::new(crate::cross_file::extract_metadata_with_tree(
                code,
                Some(&tree),
            ));
            graph.update_file(uri, &meta, Some(&workspace_root), |_| None);
            metas.insert((*uri).clone(), meta);
        }

        // Sanity: the edges that make this a regression must actually exist.
        assert_eq!(
            graph.get_dependents(&indices_uri).len(),
            1,
            "indices.r should have data.r as its sole parent"
        );
        assert_eq!(
            graph.get_dependents(&data_uri).len(),
            2,
            "data.r should be sourced by both main.r and D.r"
        );

        let artifacts_for_closure = artifacts.clone();
        let get_artifacts = move |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
            artifacts_for_closure.get(uri).cloned()
        };
        let metas_for_closure = metas.clone();
        let get_metadata = move |uri: &Url| -> Option<std::sync::Arc<CrossFileMetadata>> {
            metas_for_closure.get(uri).cloned()
        };

        // Query indices.r at the top-level use of `ww.covars` via the cached
        // path — the one the diagnostic snapshot uses. It seeds
        // `visited[indices.r] = (MAX, MAX)` for the prefix computation, which is
        // what let the deep parent walk contaminate `visited[covariates.r]`.
        // `hoist_globals = true` with a top-level position resolves the
        // `inside = false` prefix slot the undefined-variable check consumes.
        let base_exports = HashSet::new();
        let mut prefix_cache = ParentPrefixCache::new();
        let scope = scope_at_position_with_graph_cached(
            &indices_uri,
            0,
            5,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &base_exports,
            true,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            &mut prefix_cache,
            None,
            None,
        );

        assert!(
            scope.symbols.contains_key("ww.covars"),
            "ww.covars (defined in earlier-sourced sibling covariates.r) must be \
             visible in indices.r; got symbols: {:?}",
            scope.symbols.keys().collect::<Vec<_>>()
        );
    }

    // ====================================================================
    // Issue #472 — forward-child memoization equivalence gate.
    //
    // The master correctness gate: for a battery of workspaces, resolving
    // every file's EOF scope with the forward-child memo ENABLED must be
    // byte-identical to resolving it DISABLED. This directly exercises the
    // package-set (`pkg_fp`), path-context (`path_fp`), and source-cycle
    // (`detect_cycle` exclusion) concerns Codex raised.
    // ====================================================================

    /// Canonical, order-independent string form of a resolved scope, covering
    /// every field that memoization could perturb.
    #[cfg(test)]
    fn canonical_scope(scope: &ScopeAtPosition) -> String {
        let mut symbols: Vec<String> = scope
            .symbols
            .iter()
            .map(|(n, s)| {
                format!(
                    "{n}|{:?}|{}|{}:{}|decl={}",
                    s.kind, s.source_uri, s.defined_line, s.defined_column, s.is_declared
                )
            })
            .collect();
        symbols.sort();
        let mut loaded: Vec<&String> = scope.loaded_packages.iter().collect();
        loaded.sort();
        let mut inherited: Vec<&String> = scope.inherited_packages.iter().collect();
        inherited.sort();
        let mut origins: Vec<String> = scope
            .package_origins
            .iter()
            .map(|(p, set)| {
                let mut us: Vec<String> = set.iter().map(|u| u.to_string()).collect();
                us.sort();
                format!("{p}=>[{}]", us.join(","))
            })
            .collect();
        origins.sort();
        let mut depth: Vec<String> = scope
            .depth_exceeded
            .iter()
            .map(|(u, l, c)| format!("{u}:{l}:{c}"))
            .collect();
        depth.sort();
        let mut chain: Vec<String> = scope.chain.iter().map(|u| u.to_string()).collect();
        chain.sort();
        let mut prefix_names: Vec<String> = scope
            .parent_prefix_symbol_names
            .iter()
            .map(|n| n.to_string())
            .collect();
        prefix_names.sort();
        let mut vis: Vec<String> = scope
            .visible_positions
            .iter()
            .map(|(u, (l, c))| format!("{u}:{l}:{c}"))
            .collect();
        vis.sort();
        format!(
            "SYM[{}]\nLOADED[{loaded:?}]\nINH[{inherited:?}]\nORIG[{}]\nDEPTH[{}]\nCHAIN[{}]\nPFX[{}]\nVIS[{}]",
            symbols.join(";"),
            origins.join(";"),
            depth.join(";"),
            chain.join(";"),
            prefix_names.join(";"),
            vis.join(";"),
        )
    }

    /// Build a graph + artifact/metadata closures from `(uri, code)` files,
    /// then assert that resolving every file's EOF scope is identical with the
    /// forward-child memo enabled vs disabled, under the given `max_depth`.
    #[cfg(test)]
    fn assert_memo_equivalence_with_depth(
        workspace_root: &Url,
        files: &[(Url, &str)],
        max_depth: usize,
    ) {
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::CrossFileMetadata;

        let mut artifacts: HashMap<Url, Arc<ScopeArtifacts>> = HashMap::new();
        let mut metas: HashMap<Url, std::sync::Arc<CrossFileMetadata>> = HashMap::new();
        let mut graph = DependencyGraph::new();
        for (uri, code) in files {
            let tree = parse_r(code);
            artifacts.insert(uri.clone(), Arc::new(compute_artifacts(uri, &tree, code)));
            let meta = std::sync::Arc::new(crate::cross_file::extract_metadata_with_tree(
                code,
                Some(&tree),
            ));
            graph.update_file(uri, &meta, Some(workspace_root), |_| None);
            metas.insert(uri.clone(), meta);
        }

        let get_artifacts =
            |uri: &Url| -> Option<Arc<ScopeArtifacts>> { artifacts.get(uri).cloned() };
        let get_metadata =
            |uri: &Url| -> Option<std::sync::Arc<CrossFileMetadata>> { metas.get(uri).cloned() };
        let base_exports = HashSet::new();

        let resolve = |uri: &Url| {
            scope_at_position_with_graph(
                uri,
                u32::MAX,
                u32::MAX,
                &get_artifacts,
                &get_metadata,
                &graph,
                Some(workspace_root),
                max_depth,
                &base_exports,
                true,
                crate::cross_file::config::BackwardDependencyMode::Auto,
                &|| false,
                None,
                None,
            )
        };

        // Resolve a file's EOF scope through the `ScopeStream` path — the
        // production undefined-variable path, where the forward-child memo is a
        // per-stream field shared between the prefix pre-computation and the
        // forward sweep.
        let resolve_stream = |uri: &Url| {
            let prefix_cache = std::cell::RefCell::new(ParentPrefixCache::new());
            let mut stream = ScopeStream::new(
                uri,
                &get_artifacts,
                &get_metadata,
                &graph,
                Some(workspace_root),
                max_depth,
                &base_exports,
                true,
                crate::cross_file::config::BackwardDependencyMode::Auto,
                &|| false,
                &prefix_cache,
                None,
                None,
            )
            .expect("stream construction must succeed");
            stream.advance_to(u32::MAX, u32::MAX);
            stream.snapshot()
        };

        for (uri, _) in files {
            FORWARD_CHILD_MEMO_DISABLED.with(|c| c.set(true));
            let off = resolve(uri);
            let off_stream = resolve_stream(uri);
            FORWARD_CHILD_MEMO_DISABLED.with(|c| c.set(false));
            let on = resolve(uri);
            let on_stream = resolve_stream(uri);
            assert_eq!(
                canonical_scope(&off),
                canonical_scope(&on),
                "forward-child memo changed the recursive resolved scope for {uri} (max_depth={max_depth})"
            );
            assert_eq!(
                canonical_scope(&off_stream),
                canonical_scope(&on_stream),
                "forward-child memo changed the ScopeStream resolved scope for {uri} (max_depth={max_depth})"
            );
        }
    }

    /// Equivalence at the production default depth.
    #[cfg(test)]
    fn assert_memo_equivalence(workspace_root: &Url, files: &[(Url, &str)]) {
        assert_memo_equivalence_with_depth(workspace_root, files, 64);
    }

    #[test]
    fn memo_equiv_depth_truncation_small_max_depth() {
        // A child reached at two different depths within one query, with a
        // chain long enough that a small max_depth truncates the deeper reach
        // but not the shallower one. The memo must NOT serve a depth-truncated
        // scope to a shallower reach (issue #472 / depth-key soundness).
        // `q` sources `a` then `c` directly; `a` also sources `c`, so `c` is
        // reached at depth 1 (q->c) and depth 2 (q->a->c). The c->d->e->f chain
        // truncates differently at those depths under max_depth=4.
        let root = Url::parse("file:///project").unwrap();
        let files: Vec<(Url, &str)> = vec![
            (
                Url::parse("file:///project/q.r").unwrap(),
                "source(\"a.r\")\nsource(\"c.r\")\n",
            ),
            (
                Url::parse("file:///project/a.r").unwrap(),
                "source(\"c.r\")\na_sym <- 1\n",
            ),
            (
                Url::parse("file:///project/c.r").unwrap(),
                "source(\"d.r\")\nc_sym <- 1\n",
            ),
            (
                Url::parse("file:///project/d.r").unwrap(),
                "source(\"e.r\")\nd_sym <- 1\n",
            ),
            (
                Url::parse("file:///project/e.r").unwrap(),
                "source(\"f.r\")\ne_sym <- 1\n",
            ),
            (Url::parse("file:///project/f.r").unwrap(), "f_sym <- 1\n"),
        ];
        for depth in [3usize, 4, 5] {
            assert_memo_equivalence_with_depth(&root, &files, depth);
        }
    }

    #[test]
    fn memo_equiv_gate_admitted_with_truncation() {
        // Issue #479 hardening — the one interaction no other `memo_equiv_*`
        // test covers: the shared-prefix-memo gate (`prefix_memo_share_safe`)
        // ADMITS sharing, yet the recursive resolver still TRUNCATES. The gate
        // admits on *shortest-path* BFS depth, while the resolver (cloned
        // `visited` per branch) can reach a node at a greater `current_depth`
        // via a *longer simple path* and truncate there. `memo_equiv_dense_hub_*`
        // admits but is too shallow to truncate; `memo_equiv_depth_truncation_*`
        // truncates but is deep enough that the gate DISABLES sharing — neither
        // hits both at once.
        //
        // Construction: hub `q` sources `a..e` directly (so every node sits at
        // BFS depth 1 from `q` and the gate admits at small `max_depth`), AND
        // `a -> b -> c -> d -> e` is chained, giving a length-5 simple path that
        // truncates under a small `max_depth`. The shared-vs-unshared memo
        // result must still be byte-identical: a truncated subtree carries a
        // non-empty `depth_exceeded` and is therefore never written to the memo
        // (`resolve_forward_child_memoized`), so a gate-admitted-but-truncating
        // graph behaves exactly like the un-shared baseline.
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::CrossFileMetadata;

        let root = Url::parse("file:///project").unwrap();
        let q = Url::parse("file:///project/q.r").unwrap();
        let a = Url::parse("file:///project/a.r").unwrap();
        let files: Vec<(Url, &str)> = vec![
            (
                q.clone(),
                "source(\"a.r\")\nsource(\"b.r\")\nsource(\"c.r\")\nsource(\"d.r\")\nsource(\"e.r\")\n",
            ),
            (a.clone(), "source(\"b.r\")\nsym_a <- 1\n"),
            (
                Url::parse("file:///project/b.r").unwrap(),
                "source(\"c.r\")\nsym_b <- 1\n",
            ),
            (
                Url::parse("file:///project/c.r").unwrap(),
                "source(\"d.r\")\nsym_c <- 1\n",
            ),
            (
                Url::parse("file:///project/d.r").unwrap(),
                "source(\"e.r\")\nsym_d <- 1\n",
            ),
            (Url::parse("file:///project/e.r").unwrap(), "sym_e <- 1\n"),
        ];

        // Build the graph + artifacts/metas once (mirrors
        // `assert_memo_equivalence_with_depth`'s internal construction) so the
        // two non-vacuity checks below can probe the gate and the truncation
        // directly.
        let mut graph = DependencyGraph::new();
        let mut artifacts: HashMap<Url, Arc<ScopeArtifacts>> = HashMap::new();
        let mut metas: HashMap<Url, std::sync::Arc<CrossFileMetadata>> = HashMap::new();
        for (uri, code) in &files {
            let tree = parse_r(code);
            artifacts.insert(uri.clone(), Arc::new(compute_artifacts(uri, &tree, code)));
            let meta = std::sync::Arc::new(crate::cross_file::extract_metadata_with_tree(
                code,
                Some(&tree),
            ));
            graph.update_file(uri, &meta, Some(&root), |_| None);
            metas.insert(uri.clone(), meta);
        }

        // Non-vacuity 1 — the gate ADMITS sharing for `q` at these small depths
        // (every node sits at BFS depth 1 from `q` via the direct edges), so the
        // shared-prefix path is genuinely active in the equivalence check below.
        for depth in [3usize, 4] {
            assert!(
                graph.prefix_memo_share_safe(&q, depth, PREFIX_MEMO_SHARE_PROBE_BUDGET),
                "gate must ADMIT q at max_depth={depth} (all nodes at BFS depth 1)"
            );
        }

        // Non-vacuity 2 — the resolver actually TRUNCATES the a->...->e chain
        // under a small `max_depth`: resolving `a` at depth 4 drops the deepest
        // chain symbol `sym_e`, while at depth 64 it is reached.
        let get_artifacts =
            |uri: &Url| -> Option<Arc<ScopeArtifacts>> { artifacts.get(uri).cloned() };
        let get_metadata =
            |uri: &Url| -> Option<std::sync::Arc<CrossFileMetadata>> { metas.get(uri).cloned() };
        let base_exports = HashSet::new();
        let resolve = |uri: &Url, depth: usize| {
            scope_at_position_with_graph(
                uri,
                u32::MAX,
                u32::MAX,
                &get_artifacts,
                &get_metadata,
                &graph,
                Some(&root),
                depth,
                &base_exports,
                true,
                crate::cross_file::config::BackwardDependencyMode::Auto,
                &|| false,
                None,
                None,
            )
        };
        assert!(
            !canonical_scope(&resolve(&a, 4)).contains("sym_e|"),
            "depth 4 must truncate the a->b->c->d->e chain before sym_e"
        );
        assert!(
            canonical_scope(&resolve(&a, 64)).contains("sym_e|"),
            "depth 64 must reach sym_e through the chain"
        );

        // The regression pin. Issue #479's shared-prefix memo guarantees the
        // resolved **symbol set** is byte-identical whether sharing is enabled
        // (gate-admitted, as proven above) or disabled — *even when the resolver
        // truncates via a longer path the BFS-shortest gate failed to exclude*.
        // This holds because a truncating resolution carries a non-empty
        // `depth_exceeded` and is never written to the memo
        // (`resolve_forward_child_memoized`'s cache guard), so the cache can
        // never feed a truncated (wrong) symbol set to another prefix root. We
        // compare the memo-enabled vs memo-disabled symbol set of every
        // gate-admitted query on BOTH the recursive path and the `ScopeStream`
        // path (where #479's shared prefix memo lives).
        //
        // We deliberately do NOT assert `depth_exceeded`/`chain` equality. Those
        // are the heuristic "Maximum chain depth exceeded" advisory channel
        // (`handlers.rs`, `exceeded_uri == uri`), and under a gate-admitted
        // graph the resolver truncates anyway — the visited-independent shared
        // memo can then emit/suppress that advisory on a file vs the un-memoized
        // resolver. That is the accepted, documented residual of WI1's
        // BFS-shortest gate (see `prefix_memo_share_safe`'s NOTE) and is tracked
        // for a fix in issue #484. It is invisible at the default
        // `maxChainDepth = 64` (no real chain is that deep) and never affects
        // symbols — which is exactly what this test pins.
        let project = |scope: &ScopeAtPosition| -> String {
            let mut syms: Vec<String> = scope
                .symbols
                .iter()
                .map(|(n, s)| {
                    format!(
                        "{n}|{:?}|{}|{}:{}|decl={}",
                        s.kind, s.source_uri, s.defined_line, s.defined_column, s.is_declared
                    )
                })
                .collect();
            syms.sort();
            format!("SYM[{}]", syms.join(";"))
        };
        let resolve_stream = |uri: &Url, depth: usize| {
            let prefix_cache = std::cell::RefCell::new(ParentPrefixCache::new());
            let mut stream = ScopeStream::new(
                uri,
                &get_artifacts,
                &get_metadata,
                &graph,
                Some(&root),
                depth,
                &base_exports,
                true,
                crate::cross_file::config::BackwardDependencyMode::Auto,
                &|| false,
                &prefix_cache,
                None,
                None,
            )
            .expect("stream construction must succeed");
            stream.advance_to(u32::MAX, u32::MAX);
            stream.snapshot()
        };
        // #479's shared prefix memo is active for a query ONLY when the gate
        // admits it, so the loop gates each query dynamically and asserts only
        // on admitted ones (that is the property #479 introduces; gate-rejected
        // queries fall back to the pre-#479 fresh-ephemeral prefix memo, covered
        // by the other `memo_equiv_*` tests). Admission here depends on
        // `max_depth`: at `max_depth=3` (`depth_cap=2`) only `q` is admitted
        // (every other file reaches `c`/`d`/`e` at BFS depth 2); at
        // `max_depth=4` (`depth_cap=3`) the whole neighborhood is BFS-shallow
        // enough that every file is admitted. `q` is admitted at both depths and
        // its per-child-source prefix computations resolve the truncating chain
        // through the shared memo, so the gate-admitted-with-truncation
        // interaction is exercised regardless.
        let mut asserted_any = false;
        for depth in [3usize, 4] {
            for (uri, _) in &files {
                if !graph.prefix_memo_share_safe(uri, depth, PREFIX_MEMO_SHARE_PROBE_BUDGET) {
                    continue;
                }
                asserted_any = true;
                FORWARD_CHILD_MEMO_DISABLED.with(|c| c.set(true));
                let off = project(&resolve(uri, depth));
                let off_stream = project(&resolve_stream(uri, depth));
                FORWARD_CHILD_MEMO_DISABLED.with(|c| c.set(false));
                let on = project(&resolve(uri, depth));
                let on_stream = project(&resolve_stream(uri, depth));
                assert_eq!(
                    off, on,
                    "forward-child memo changed the recursive symbol set for {uri} (max_depth={depth})"
                );
                assert_eq!(
                    off_stream, on_stream,
                    "shared prefix memo changed the ScopeStream symbol set for {uri} (max_depth={depth})"
                );
            }
        }
        assert!(
            asserted_any,
            "fixture must exercise at least one gate-admitted query (else the test is vacuous)"
        );
    }

    #[test]
    fn memo_equiv_dense_hub_shared_children() {
        // A hub sources many children; a bootstrap sources the hub; many leaves
        // source the bootstrap. Children are reached via many paths → many memo
        // hits. Each child defines a symbol and loads a package.
        let root = Url::parse("file:///project").unwrap();
        let mut files: Vec<(Url, String)> = Vec::new();
        let n = 12;
        let mut hub_code = String::new();
        for i in 0..n {
            hub_code.push_str(&format!("source(\"child_{i}.r\")\n"));
            files.push((
                Url::parse(&format!("file:///project/child_{i}.r")).unwrap(),
                format!("library(pkg{i})\ngetSym_{i} <- function() {i}\n"),
            ));
        }
        files.push((Url::parse("file:///project/functions.r").unwrap(), hub_code));
        files.push((
            Url::parse("file:///project/bootstrap.r").unwrap(),
            "source(\"functions.r\")\n".to_string(),
        ));
        for l in 0..5 {
            files.push((
                Url::parse(&format!("file:///project/leaf_{l}.r")).unwrap(),
                "source(\"bootstrap.r\")\n".to_string(),
            ));
        }
        let borrowed: Vec<(Url, &str)> =
            files.iter().map(|(u, c)| (u.clone(), c.as_str())).collect();
        assert_memo_equivalence(&root, &borrowed);
    }

    #[test]
    fn memo_dedups_forward_child_resolutions() {
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::CrossFileMetadata;

        // `hub.r` sources N children. `q.r` (queried) sources the hub. `q.r`
        // has K parents that each source the hub *before* sourcing `q.r`, so
        // STEP 1's backward walk expands the hub's children at EOF, and STEP 2
        // of `q.r` re-resolves them (the #471 regression). The memo must
        // collapse the STEP-2 re-resolution to cache hits.
        let root = Url::parse("file:///project").unwrap();
        let n = 10usize;
        let k = 6usize;
        let mut files: Vec<(Url, String)> = Vec::new();
        let mut hub_code = String::new();
        for i in 0..n {
            hub_code.push_str(&format!("source(\"child_{i}.r\")\n"));
            files.push((
                Url::parse(&format!("file:///project/child_{i}.r")).unwrap(),
                format!("c_sym_{i} <- {i}\n"),
            ));
        }
        files.push((Url::parse("file:///project/hub.r").unwrap(), hub_code));
        files.push((
            Url::parse("file:///project/q.r").unwrap(),
            "source(\"hub.r\")\n".to_string(),
        ));
        for j in 0..k {
            files.push((
                Url::parse(&format!("file:///project/p_{j}.r")).unwrap(),
                // hub BEFORE q, so at q's call site the hub is already expanded.
                "source(\"hub.r\")\nsource(\"q.r\")\n".to_string(),
            ));
        }

        let mut artifacts: HashMap<Url, Arc<ScopeArtifacts>> = HashMap::new();
        let mut metas: HashMap<Url, std::sync::Arc<CrossFileMetadata>> = HashMap::new();
        let mut graph = DependencyGraph::new();
        for (uri, code) in &files {
            let tree = parse_r(code);
            artifacts.insert(uri.clone(), Arc::new(compute_artifacts(uri, &tree, code)));
            let meta = std::sync::Arc::new(crate::cross_file::extract_metadata_with_tree(
                code,
                Some(&tree),
            ));
            graph.update_file(uri, &meta, Some(&root), |_| None);
            metas.insert(uri.clone(), meta);
        }
        let get_artifacts = |uri: &Url| artifacts.get(uri).cloned();
        let get_metadata = |uri: &Url| metas.get(uri).cloned();
        let base_exports = HashSet::new();
        let q_uri = Url::parse("file:///project/q.r").unwrap();

        let resolve_and_count = |disabled: bool| -> u64 {
            FORWARD_CHILD_MEMO_DISABLED.with(|c| c.set(disabled));
            FORWARD_CHILD_COMPUTE_COUNT.with(|c| c.set(0));
            let _ = scope_at_position_with_graph(
                &q_uri,
                u32::MAX,
                u32::MAX,
                &get_artifacts,
                &get_metadata,
                &graph,
                Some(&root),
                64,
                &base_exports,
                true,
                crate::cross_file::config::BackwardDependencyMode::Auto,
                &|| false,
                None,
                None,
            );
            let count = FORWARD_CHILD_COMPUTE_COUNT.with(|c| c.get());
            FORWARD_CHILD_MEMO_DISABLED.with(|c| c.set(false));
            count
        };

        let off = resolve_and_count(true);
        let on = resolve_and_count(false);

        // With the memo on, each distinct forward-sourced file (the hub + its N
        // children) is resolved at most once.
        assert!(
            on <= (n + 1) as u64,
            "memo should resolve each forward child at most once: on={on}, n+1={}",
            n + 1
        );
        // Without it, STEP 2 re-resolves the hub + children that STEP 1's
        // backward walk already expanded.
        assert!(
            off > on,
            "expected the un-memoized path to re-resolve more often: off={off}, on={on}"
        );
    }

    #[test]
    fn memo_keys_on_data_alias_provider() {
        // Regression: the memo key must include the DataAliasProvider identity.
        // `x.r` does `library(survey); data(api)`, which (with a provider)
        // binds the dataset objects apiclus1/apistrat. `q.r` (queried) sources
        // x.r — forward path, real provider. `p.r` sources x.r BEFORE q.r, so
        // STEP 1's backward walk (q -> p) resolves x.r with provider=None and
        // would, without the provider in the key, cache an alias-free x.r scope
        // that the forward path then reuses, dropping apiclus1/apistrat.
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::CrossFileMetadata;

        // `survey` is provided via the provider's base_packages (not a
        // `library()` call in x.r), so x.r loads no package and nothing
        // propagates back to p/q. That keeps `pkg_fp` and `path_fp` identical
        // between the backward (p->x, provider=None) and forward (q->x,
        // provider=Some) resolutions, so `provider_fp` is the ONLY thing
        // separating their memo keys — exactly the collision under test.
        let root = Url::parse("file:///project").unwrap();
        let files: [(Url, &str); 3] = [
            (
                Url::parse("file:///project/x.r").unwrap(),
                "data(api)\nx_sym <- 1\n",
            ),
            (
                Url::parse("file:///project/q.r").unwrap(),
                "source(\"x.r\")\n",
            ),
            (
                Url::parse("file:///project/p.r").unwrap(),
                "source(\"x.r\")\nsource(\"q.r\")\n",
            ),
        ];

        let mut artifacts: HashMap<Url, Arc<ScopeArtifacts>> = HashMap::new();
        let mut metas: HashMap<Url, std::sync::Arc<CrossFileMetadata>> = HashMap::new();
        let mut graph = DependencyGraph::new();
        for (uri, code) in &files {
            let tree = parse_r(code);
            artifacts.insert(uri.clone(), Arc::new(compute_artifacts(uri, &tree, code)));
            let meta = std::sync::Arc::new(crate::cross_file::extract_metadata_with_tree(
                code,
                Some(&tree),
            ));
            graph.update_file(uri, &meta, Some(&root), |_| None);
            metas.insert(uri.clone(), meta);
        }
        let get_artifacts = |u: &Url| artifacts.get(u).cloned();
        let get_metadata = |u: &Url| metas.get(u).cloned();
        let base_exports = HashSet::new();
        let base_packages: HashSet<String> = ["survey".to_string()].into_iter().collect();
        let lookup = fake_alias_lookup;
        let provider = DataAliasProvider {
            lookup: &lookup,
            base_packages: &base_packages,
        };
        let q = Url::parse("file:///project/q.r").unwrap();
        let scope = scope_at_position_with_graph(
            &q,
            u32::MAX,
            u32::MAX,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&root),
            64,
            &base_exports,
            true,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            None,
            Some(&provider),
        );
        assert!(
            scope.symbols.contains_key("apiclus1") && scope.symbols.contains_key("apistrat"),
            "data(api) aliases from forward-sourced x.r must reach q.r; the memo must \
             not serve the backward walk's provider-less x.r scope. got: {:?}",
            scope.symbols.keys().collect::<Vec<_>>()
        );
    }

    #[test]
    fn memo_equiv_source_cycle() {
        // A ↔ B source cycle plus a child sourced by both. Cyclic files are
        // excluded from the memo; equivalence must still hold and not loop.
        let root = Url::parse("file:///project").unwrap();
        let files: Vec<(Url, &str)> = vec![
            (
                Url::parse("file:///project/a.r").unwrap(),
                "source(\"b.r\")\nsource(\"shared.r\")\na_sym <- 1\n",
            ),
            (
                Url::parse("file:///project/b.r").unwrap(),
                "source(\"a.r\")\nsource(\"shared.r\")\nb_sym <- 2\n",
            ),
            (
                Url::parse("file:///project/shared.r").unwrap(),
                "shared_sym <- 3\n",
            ),
        ];
        assert_memo_equivalence(&root, &files);
    }

    #[test]
    fn memo_equiv_cd_divergence() {
        // The same-named child is sourced by two parents under different
        // `# raven: cd` working directories, so each parent's child resolves a
        // different `helper.r`. `path_fp` must keep the two from colliding.
        let root = Url::parse("file:///project").unwrap();
        let files: Vec<(Url, &str)> = vec![
            (
                Url::parse("file:///project/p1.r").unwrap(),
                "# raven: cd dirA\nsource(\"sub.r\")\n",
            ),
            (
                Url::parse("file:///project/p2.r").unwrap(),
                "# raven: cd dirB\nsource(\"sub.r\")\n",
            ),
            (
                Url::parse("file:///project/sub.r").unwrap(),
                "source(\"helper.r\")\n",
            ),
            (
                Url::parse("file:///project/dirA/helper.r").unwrap(),
                "helperA <- 1\n",
            ),
            (
                Url::parse("file:///project/dirB/helper.r").unwrap(),
                "helperB <- 2\n",
            ),
        ];
        assert_memo_equivalence(&root, &files);
    }

    #[test]
    fn test_package_propagation_grandchild_packages_in_grandparent() {
        // Packages loaded in deeply nested sourced files should propagate
        // back through the chain after source() calls.
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::{CrossFileMetadata, ForwardSource};

        // Grandparent file: source("parent.R")
        let grandparent_code = "source(\"parent.R\")\nz <- 1";
        let grandparent_tree = parse_r(grandparent_code);
        let grandparent_uri = Url::parse("file:///project/grandparent.R").unwrap();
        let grandparent_artifacts =
            compute_artifacts(&grandparent_uri, &grandparent_tree, grandparent_code);

        // Parent file: source("child.R")
        let parent_code = "source(\"child.R\")\ny <- 1";
        let parent_tree = parse_r(parent_code);
        let parent_uri = Url::parse("file:///project/parent.R").unwrap();
        let parent_artifacts = compute_artifacts(&parent_uri, &parent_tree, parent_code);

        // Child file: loads stringr
        let child_code = "library(stringr)\nx <- 1";
        let child_tree = parse_r(child_code);
        let child_uri = Url::parse("file:///project/child.R").unwrap();
        let child_artifacts = compute_artifacts(&child_uri, &child_tree, child_code);

        let workspace_root = Url::parse("file:///project").unwrap();

        // Build dependency graph
        let mut graph = DependencyGraph::new();

        let grandparent_meta = CrossFileMetadata {
            sources: vec![ForwardSource {
                path: "parent.R".to_string(),
                line: 0,
                column: 0,
                is_directive: false,
                chdir: false,
                is_sys_source: false,
                ..Default::default()
            }],
            ..Default::default()
        };
        graph.update_file(
            &grandparent_uri,
            &grandparent_meta,
            Some(&workspace_root),
            |_| None,
        );

        let parent_meta = CrossFileMetadata {
            sources: vec![ForwardSource {
                path: "child.R".to_string(),
                line: 0,
                column: 0,
                is_directive: false,
                chdir: false,
                is_sys_source: false,
                ..Default::default()
            }],
            ..Default::default()
        };
        graph.update_file(&parent_uri, &parent_meta, Some(&workspace_root), |_| None);

        let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
            if uri == &grandparent_uri {
                Some(Arc::new(grandparent_artifacts.clone()))
            } else if uri == &parent_uri {
                Some(Arc::new(parent_artifacts.clone()))
            } else if uri == &child_uri {
                Some(Arc::new(child_artifacts.clone()))
            } else {
                None
            }
        };

        let get_metadata = |uri: &Url| -> Option<std::sync::Arc<CrossFileMetadata>> {
            if uri == &grandparent_uri {
                Some(std::sync::Arc::new(grandparent_meta.clone()))
            } else if uri == &parent_uri {
                Some(std::sync::Arc::new(parent_meta.clone()))
            } else {
                None
            }
        };

        // Query grandparent's scope after source() call
        let grandparent_scope = scope_at_position_with_graph(
            &grandparent_uri,
            1,
            0,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Explicit,
            &|| false,
            None,
            None,
        );

        // Grandparent should have stringr (loaded in grandchild, propagated via loaded_packages)
        assert!(
            grandparent_scope.loaded_packages.contains("stringr"),
            "Grandparent should have stringr from grandchild (package propagation via loaded_packages)"
        );

        // Query parent's scope after source() call
        let parent_scope = scope_at_position_with_graph(
            &parent_uri,
            1,
            0,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Explicit,
            &|| false,
            None,
            None,
        );

        // Parent should also have stringr (loaded in child, propagated via loaded_packages)
        assert!(
            parent_scope.loaded_packages.contains("stringr"),
            "Parent should have stringr from child (package propagation via loaded_packages)"
        );
    }

    #[test]
    fn test_package_propagation_parent_and_child_packages_both_available() {
        // Combined test: Parent's packages propagate to child, and child's packages
        // propagate back to parent after source().
        use crate::cross_file::dependency::DependencyGraph;
        use crate::cross_file::types::{CrossFileMetadata, ForwardSource};

        // Parent file: library(dplyr), source("child.R")
        let parent_code = "library(dplyr)\nsource(\"child.R\")\nz <- 1";
        let parent_tree = parse_r(parent_code);
        let parent_uri = Url::parse("file:///project/parent.R").unwrap();
        let parent_artifacts = compute_artifacts(&parent_uri, &parent_tree, parent_code);

        // Child file: loads ggplot2
        let child_code = "library(ggplot2)\nx <- 1";
        let child_tree = parse_r(child_code);
        let child_uri = Url::parse("file:///project/child.R").unwrap();
        let child_artifacts = compute_artifacts(&child_uri, &child_tree, child_code);

        let workspace_root = Url::parse("file:///project").unwrap();

        // Build dependency graph
        let mut graph = DependencyGraph::new();
        let parent_meta = CrossFileMetadata {
            sources: vec![ForwardSource {
                path: "child.R".to_string(),
                line: 1,
                column: 0,
                is_directive: false,
                chdir: false,
                is_sys_source: false,
                ..Default::default()
            }],
            ..Default::default()
        };
        graph.update_file(&parent_uri, &parent_meta, Some(&workspace_root), |_| None);

        let get_artifacts = |uri: &Url| -> Option<Arc<ScopeArtifacts>> {
            if uri == &parent_uri {
                Some(Arc::new(parent_artifacts.clone()))
            } else if uri == &child_uri {
                Some(Arc::new(child_artifacts.clone()))
            } else {
                None
            }
        };

        let get_metadata = |uri: &Url| -> Option<std::sync::Arc<CrossFileMetadata>> {
            if uri == &parent_uri {
                Some(std::sync::Arc::new(parent_meta.clone()))
            } else {
                None
            }
        };

        // Query child's scope - should have dplyr from parent
        let child_scope = scope_at_position_with_graph(
            &child_uri,
            0,
            0,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            None,
            None,
        );

        // Child SHOULD have dplyr (propagated from parent)
        assert!(
            child_scope.inherited_packages.contains("dplyr"),
            "Child should inherit dplyr from parent (forward propagation works)"
        );

        // Query parent's scope after source() call
        let parent_scope = scope_at_position_with_graph(
            &parent_uri,
            2,
            0,
            &get_artifacts,
            &get_metadata,
            &graph,
            Some(&workspace_root),
            10,
            &HashSet::new(),
            false,
            crate::cross_file::config::BackwardDependencyMode::Auto,
            &|| false,
            None,
            None,
        );

        // Parent should have ggplot2 (loaded in child, propagated via loaded_packages)
        assert!(
            parent_scope.loaded_packages.contains("ggplot2"),
            "Parent should have ggplot2 from child (package propagation via loaded_packages)"
        );
    }

    // ============================================================================
